FIXES_119["source/structures/structure_render.c#surfacesort"] = [
("""static void structure_render_dynamic_triangles_from_indices(
	short surface_count,
	long *surface_indices,
	short *triangles)
{
	struct structure_bsp *structure_bsp = global_structure_bsp_get();
	short surface_index_index;

	qsort_4byte(surface_indices, surface_count, compare_surface_indices);
""",
 """#ifdef HALO_PSP
#include <stdlib.h>
#include <string.h>

unsigned long psp_surface_sorts = 0, psp_surface_sorts_in_order = 0, psp_surface_sort_mismatches = 0,
	psp_surface_sorts_by_bits = 0;

/* build 119: a list of surface indices put in order through a bit per
surface (the BSP's own surface count): each index sets its bit, and the set
bits are read back in order. With no index twice (the light pass's lists
hold each surface once), the list comes out as the sort's. An index out of
range or seen twice: 0, and the sort does it. The bits are kept on the heap
and grow with the largest BSP seen */
static unsigned long *psp_surface_bits = NULL;
static long psp_surface_bit_words = 0;

static int psp_order_surface_indices_by_bits(
	long *elements,
	long element_count,
	long surface_count)
{
	long words = (surface_count + 31) >> 5, k, w;

	if (surface_count <= 0)
		return 0;
	if (words > psp_surface_bit_words)
	{
		unsigned long *more = malloc(words * sizeof(unsigned long));

		if (!more)
			return 0;
		/* (never free(NULL) here: this build's free reads a block's
		header before the pointer, and faulted at 0xffffffe0) */
		if (psp_surface_bits)
			free(psp_surface_bits);
		psp_surface_bits = more;
		psp_surface_bit_words = words;
	}
	memset(psp_surface_bits, 0, words * sizeof(unsigned long));
	for (k = 0; k < element_count; k++)
	{
		long index = elements[k];
		unsigned long bit;

		if (index < 0 || index >= surface_count)
			return 0;
		bit = 1ul << (index & 31);
		if (psp_surface_bits[index >> 5] & bit)
			return 0;
		psp_surface_bits[index >> 5] |= bit;
	}
	for (w = 0, k = 0; w < words; w++)
	{
		unsigned long bits = psp_surface_bits[w];

		while (bits)
		{
			unsigned long lowest = bits & (0ul - bits);

			elements[k++] = (w << 5) + (31 - __builtin_clz(lowest));
			bits ^= lowest;
		}
	}
	return 1;
}

/* each index above the one before it: the list is its own sort */
static int psp_surface_indices_ascending(
	long const *elements,
	long element_count)
{
	long k;

	for (k = 1; k < element_count; k++)
		if (elements[k - 1] >= elements[k])
			return 0;
	return 1;
}

/* psp_fixups.py (build 119): qsort_4byte (cseries/sort.c) for
compare_surface_indices, its comparison (a > b) written in */
static void psp_sort_surface_indices(
	long *elements,
	unsigned long element_count)
{
	long *lo_stack[30];
	long *hi_stack[30];
	long *lo, *hi, *i, *j, *mid;
	long depth;
	unsigned long size, k;
	long temp;

	if (element_count<2)
		return;
	/* already in order (no element above the next): nothing to move */
	for (k = 1; k < element_count && !(elements[k - 1] > elements[k]); k++)
		;
	if (k == element_count)
	{
		psp_surface_sorts_in_order++;
		return;
	}

	lo = elements;
	depth = 0;
	hi = elements+element_count-1;

	for (;;)
	{
		size = hi-lo+1;
		if (size<=8)
		{
			/* shortsort_4byte */
			long *best, *scan;
			long *top = hi;

			while (top>lo)
			{
				best = lo;
				for (scan = lo+1; scan<=top; scan++)
				{
					if (*scan > *best)
						best = scan;
				}

				temp = *best;
				*best = *top;
				*top = temp;

				top--;
			}
		}
		else
		{
			mid = lo+(size>>1);
			temp = *mid;
			*mid = *lo;
			*lo = temp;

			i = lo;
			j = hi+1;

			for (;;)
			{
				do
				{
					i++;
				}
				while (i<=hi && !(*i > *lo));

				do
				{
					j--;
				}
				while (j>lo && *j > *lo);

				if (j<i)
					break;

				temp = *i;
				*i = *j;
				*j = temp;
			}

			temp = *lo;
			*lo = *j;
			*j = temp;

			if ((char *)j-(char *)lo-1>=(char *)hi-(char *)i)
			{
				if (lo+1<j)
				{
					lo_stack[depth] = lo;
					hi_stack[depth] = j-1;
					depth++;
				}
				if (i<hi)
				{
					lo = i;
					continue;
				}
			}
			else
			{
				if (i<hi)
				{
					lo_stack[depth] = i;
					hi_stack[depth] = hi;
					depth++;
				}
				if (lo+1<j)
				{
					hi = j-1;
					continue;
				}
			}
		}

		if (--depth<0)
			break;

		lo = lo_stack[depth];
		hi = hi_stack[depth];
	}
}
#endif

static void structure_render_dynamic_triangles_from_indices(
	short surface_count,
	long *surface_indices,
	short *triangles)
{
	struct structure_bsp *structure_bsp = global_structure_bsp_get();
	short surface_index_index;

#ifdef HALO_PSP
	{
		extern int psp_keep(const char *name);
		static int old = -1, check = 0, in_order = 1;

		if (old < 0)
		{
			old = psp_keep("surfaceqsort");
			check = psp_keep("surfacesortcheck");
			/* a list already ascending (lightplan's are) is left as it is:
			its sort is itself; "surfaceinorderoff" sorts it anyway */
			in_order = !psp_keep("surfaceinorderoff");
		}
		if (old)
			qsort_4byte(surface_indices, surface_count, compare_surface_indices);
		else if (check && surface_count > 1)
		{
			/* "surfacesortcheck": the old sort on a copy, the two compared */
			long *copy = malloc(surface_count * sizeof(long));

			if (copy)
				memcpy(copy, surface_indices, surface_count * sizeof(long));
			if (psp_order_surface_indices_by_bits(surface_indices, surface_count, structure_bsp->surfaces.count))
				psp_surface_sorts_by_bits++;
			else
				psp_sort_surface_indices(surface_indices, surface_count);
			if (copy)
			{
				qsort_4byte(copy, surface_count, compare_surface_indices);
				if (memcmp(copy, surface_indices, surface_count * sizeof(long)))
					psp_surface_sort_mismatches++;
				free(copy);
			}
		}
		else if (in_order && psp_surface_indices_ascending(surface_indices, surface_count))
			psp_surface_sorts_in_order++;
		else if (psp_order_surface_indices_by_bits(surface_indices, surface_count, structure_bsp->surfaces.count))
			psp_surface_sorts_by_bits++;
		else
			psp_sort_surface_indices(surface_indices, surface_count);
		psp_surface_sorts++;
	}
#else
	qsort_4byte(surface_indices, surface_count, compare_surface_indices);
#endif
"""),
]

