# ---------- "mevis" (option C's second step): the frame's visibility made a
# second time, on the Media Engine,
# from the same camera, timed there and checked against the main CPU's
# answer. A measurement of what C's walk would cost on the ME beside today's
# drawing; the frame still draws from the main CPU's answer. The ME runs the
# engine's own code: every function of structure_visibility.c that touches
# state the frame or the tick writes (render, the portal walk's globals and
# counters, the hull cache, the warnings) is copied here as psp_mv_<name>,
# with that state moved into one block of its own (psp_mv_state, lines
# nothing else uses), its logs, asserts' messages, profile meters and debug
# drawing left out, and the copies calling each other. The functions that
# touch none of it (the hull clipping, the rectangle tests) are shared. Made
# from the fixed text at build time, so the copies follow every fixup.
MEVIS_STATE = {
    "render": "psp_mv->render", "structure_visibility_globals": "psp_mv->svg",
    "psp_hull_cache": "psp_mv->hull_cache", "psp_hull_hits": "psp_mv->counter",
    "psp_hull_misses": "psp_mv->counter", "psp_portal_walk_id": "psp_mv->walk_id",
    "psp_portal_steps": "psp_mv->portal_steps", "psp_portal_walks": "psp_mv->counter",
    "psp_portal_fallbacks": "psp_mv->counter", "psp_portal_step_total": "psp_mv->counter",
    "psp_pvs_fallback": "psp_mv->pvs_fallback", "psp_visrect_mode": "psp_mv->visrect_mode",
    "psp_visrect_skipped": "psp_mv->counter", "psp_visrect_check_kept": "psp_mv->counter",
    "error": "psp_mv_error", "platform_psp_log": "psp_mv_log", "psp_keep": "psp_mv_keep",
    "rendered_cluster_get": "psp_mv_rendered_cluster_get", "render_debug_line": "psp_mv_debug_line",
    "ai_debug_highlight_cluster": "psp_mv_debug_cluster", "profile_enter": "PSP_MV_NOPROFILE",
    "profile_exit": "PSP_MV_NOPROFILE", "psp_step": "PSP_MV_NOSTEP",
}
MEVIS_FUNCTION = re.compile(r"^((?:static\s+)?(?:__inline__\s+)?[A-Za-z_][\w \t\*]*?)\b([A-Za-z_]\w*)\((?:[^;{}\n]*\)\n|\n)", re.M)


def mevis_functions(text):
    """{name: (header, body)} for each function defined at the file's top
    level (a prototype ends in ';' before any line that is a lone '{')"""
    found = {}
    for m in MEVIS_FUNCTION.finditer(text):
        name = m.group(2)
        open_at = text.find("\n{\n", m.end() - 1)
        if open_at < 0:
            continue
        header = text[m.start():open_at + 1]
        if re.search(r"\);\s*$", header, re.M) or name in ("if", "for", "while", "switch", "return"):
            continue
        close_at = text.find("\n}\n", open_at)
        if close_at < 0:
            continue
        # a signature split by #ifdef (portal_hull_from_portal_uncached):
        # the PSP's side, as the PSP compiles it
        header = re.sub(r"\n#else\n.*?\n#endif\n", "\n", header, flags=re.S)
        if "#" in header:
            continue
        found[name] = (header, text[open_at + 1:close_at + 3])
    return found


def mevis_copies(tree):
    rel = "source/structures/structure_visibility.c"
    path = os.path.join(tree, rel)
    text = open(path, errors="surrogateescape").read()
    if "psp_mv_state" in text:
        return 0
    functions = mevis_functions(text)
    state = re.compile(r"\b(%s|warned_about_\w+)\b" % "|".join(sorted(MEVIS_STATE, key=len, reverse=True)))
    copied = {name for name, (header, body) in functions.items() if state.search(body)}
    while True:
        calls = re.compile(r"\b(%s)\(" % "|".join(sorted(copied, key=len, reverse=True)))
        more = {name for name, (header, body) in functions.items() if name not in copied and calls.search(body)}
        if not more:
            break
        copied |= more
    rename = re.compile(r"\b(%s)\b" % "|".join(sorted(copied, key=len, reverse=True)))

    def convert(piece):
        piece = rename.sub(lambda m: "psp_mv_" + m.group(1), piece)
        piece = state.sub(lambda m: "psp_mv->warned" if m.group(1).startswith("warned_about_") else MEVIS_STATE[m.group(1)],
                          piece)
        # the function's own statics (visdump's) as plain locals
        piece = re.sub(r"\bstatic (int|unsigned long) (\w+) = -?\d+;", r"\1 \2 = 0;", piece)
        return piece

    order = [name for name in functions if name in copied]
    # the file's macros that name the state (PSP_PVS_FALLBACK), made again
    # for the copies
    macros, restore = "", ""
    for m in re.finditer(r"^#define (\w+) ([^\n]*)$", text, re.M):
        if state.search(m.group(2)) and "(" not in m.group(1):
            macros += "#undef %s\n#define %s (%s)\n" % (m.group(1), m.group(1), convert(m.group(2)))
            restore += "#undef %s\n#define %s %s\n" % (m.group(1), m.group(1), m.group(2))
    out = ["\n#ifdef HALO_PSP\n/* mevis's copies (psp_fixups.py mevis_copies): %s */\n" % ", ".join(order)]
    out.append(MEVIS_HEAD)
    out.append(macros)
    for name in order:
        header, body = functions[name]
        out.append(convert(header).replace("__inline__ ", "").rstrip("\n") + ";\n")
    for name in order:
        header, body = functions[name]
        header = convert(header)
        body = convert(body)
        if name == "structure_visibility_traverse_cluster":
            # (the copy's recursion goes through a depth check: psp_mv_deeper)
            header = header.replace("psp_mv_structure_visibility_traverse_cluster(", "psp_mv_traverse_cluster_body(")
        if name in ("structure_visibility_traverse_cluster", "structure_visibility_traverse_subclusters",
                    "structure_visibility_find_objects"):
            body = body.replace("{\n", "{\n\tpsp_me_ring_step(0x5649);\n", 1)
        out.append("\n" + header.replace("__inline__ ", "") + body)
    out.append(MEVIS_TAIL)
    # (what follows in the file, appended later, as before)
    out.append(restore + "#undef PSP_STEP\n#define PSP_STEP(name) psp_step(name)\n")
    out.append("#endif\n")
    open(path, "w", errors="surrogateescape").write(text + "".join(out))
    return len(order)

MEVIS_HEAD = r"""
#undef PSP_STEP
#define PSP_STEP(name) ((void)0)
#define PSP_MV_NOSTEP(name) ((void)0)
#define PSP_MV_NOPROFILE(meter) ((void)0)
#define psp_mv_debug_line(...) ((void)0)
#define psp_mv_debug_cluster(...) 0 /* (ai_debug_highlight_cluster: never, here) */
/* the most clusters deep the ME's portal walk goes; deeper, the walk stops
there, counted, and mevisland makes that frame's visibility on the main CPU
instead. Measured (mevl6, six maps): ~18 KB of stack plus ~3.5 KB a cluster
level, the deepest walk 12 clusters (b30, 60 KB; c20 5, a10 3). 14 holds it
with room on 72 KB (the heap is what the level's copies and the textures
live on) */
#define PSP_MV_DEPTH 14
#define PSP_MV_STACK (72 * 1024)
/* the stack's lowest words, set at its allocation and checked after each
walk: a walk that ran past its stack is reported, and its answer not used */
#define PSP_MV_CANARY_WORDS 64
#define PSP_MV_CANARY 0x5A5AA5A5u
void psp_me_ring_step(unsigned int step); /* psp_me.c: an audio block waiting is mixed */

/* the copies' state: written only by the ME (the main CPU clears it once, at
its allocation), on 64-byte lines of its own */
struct psp_mv_state
{
	struct structure_visibility_globals svg;
	__typeof__(psp_hull_cache) hull_cache;
	unsigned long walk_id, counter, too_deep;
	long portal_steps;
	boolean pvs_fallback, warned;
	int visrect_mode;
	short depth, depth_most;
	unsigned long object_marks[(MAXIMUM_OBJECTS_PER_MAP + 31) / 32];
	long objects[MAXIMUM_RENDERED_OBJECTS];
	/* last, so the block can end before the render globals' surface index
	list (64 KB), which the PSP's walk never writes and nothing here reads */
	struct render_globals render;
} __attribute__((aligned(64)));
#define PSP_MV_RENDER_BYTES offsetof(struct render_globals, environment_surface_indices)
#define PSP_MV_STATE_BYTES ((offsetof(struct psp_mv_state, render) + PSP_MV_RENDER_BYTES + 63) & ~63u)
/* set once by the main CPU before the first job; the ME only reads them */
static struct psp_mv_state *psp_mv;
static void *psp_mv_stack_top;
static unsigned int *psp_mv_stack_bottom;
/* MEVISEDRAM (the lab's memory_stones row 3; "mevisedramoff" keeps them on
the heap): the state and the
walk's stack in the ME's eDRAM, 0-192 KB, which nothing else uses (edramcheck:
no hash moved there over the ladder), 152 KB off the heap. The main CPU can't
reach the eDRAM, so the ME copies what the main CPU reads (the clusters, the
surfaces and the objects) into psp_mv_handed, in main RAM, at the walk's end, and
checks its stack itself. psp_mv and the stack are then the ME's addresses:
nothing on the main CPU may touch them */
struct psp_mv_handed
{
	unsigned long visible_cluster_flags[MAXIMUM_CLUSTERS_PER_STRUCTURE / LONG_BITS];
	struct rendered_cluster rendered_clusters[MAXIMUM_RENDERED_CLUSTERS];
	long objects[MAXIMUM_RENDERED_OBJECTS];
	short rendered_cluster_count, environment_surface_count;
	unsigned int stack_low;
} __attribute__((aligned(64)));
#define PSP_MV_ME_EDRAM 0x80000000u /* psp_me.h's ME_EDRAM: the eDRAM as the ME sees it */
#define PSP_MV_EDRAM_TOP 0x30000u /* the stack's top: the end of 0-192 KB */
/* (more than the ring's whole-cache bound, 16 KB, so the ME writes its whole
cache back at the job's end, the record's lines with it) */
typedef char psp_mv_out_whole_cache[sizeof(struct psp_mv_handed) > 16 * 1024 ? 1 : -1];
static int psp_mv_edram;
static struct psp_mv_handed *psp_mv_handed;
/* the surfaces' bits handed back, sized to the largest BSP met so far rather
than the engine's 131,072 surfaces (16 KB): it grows at a BSP switch and never
shrinks, so a map's heap low sees it. Outside psp_mv_handed, it reaches main
RAM by the same whole-cache write-back (above); the job gets its address and
size in the record (pad_in[1], pad_in[2]), not from these, which the ME's
cache could hold stale */
static unsigned long *psp_mv_surface_flags;
static unsigned int psp_mv_surface_bytes;

static void psp_mv_error(long priority, char const *format, ...)
{
	(void)priority;
	(void)format;
}

static void psp_mv_log(char const *format, ...)
{
	(void)format;
}

static int psp_mv_keep(char const *name)
{
	(void)name;
	return 0;
}

static struct rendered_cluster *psp_mv_rendered_cluster_get(short rendered_cluster_index)
{
	return &psp_mv->render.rendered_clusters[rendered_cluster_index];
}
"""

MEVIS_TAIL = r"""
static void psp_mv_structure_visibility_traverse_cluster(
	short cluster_index,
	struct portal_hull const *visible_region)
{
	if (psp_mv->depth >= PSP_MV_DEPTH)
	{
		psp_mv->too_deep++;
		return;
	}
	if (++psp_mv->depth > psp_mv->depth_most)
		psp_mv->depth_most = psp_mv->depth;
	psp_mv_traverse_cluster_body(cluster_index, visible_region);
	psp_mv->depth--;
}

static boolean psp_mv_unmarked(long object_index)
{
	unsigned long k = DATUM_INDEX_TO_ABSOLUTE_INDEX(object_index) % MAXIMUM_OBJECTS_PER_MAP;

	return !(psp_mv->object_marks[k >> 5] & (1UL << (k & 31)));
}

static boolean psp_mv_mark(long object_index)
{
	unsigned long k = DATUM_INDEX_TO_ABSOLUTE_INDEX(object_index) % MAXIMUM_OBJECTS_PER_MAP;
	boolean was = !(psp_mv->object_marks[k >> 5] & (1UL << (k & 31)));

	psp_mv->object_marks[k >> 5] |= 1UL << (k & 31);
	return was;
}

/* the job's record: the camera in, the answers out, each part on lines of
its own (the main CPU writes the first, the ME the second) */
#define PSP_MV_HEAD_BYTES offsetof(struct render_globals, visible_cluster_flags)
struct psp_mv_record
{
	unsigned char head[(PSP_MV_HEAD_BYTES + 63) & ~63];
	int visrect_mode;
	unsigned int fpu_control, pad_in[14];
	unsigned int done, clusters, cluster_hash, surfaces, surface_hash, objects, object_hash;
	unsigned int cycles_clusters, cycles_objects, depth_most, too_deep, pvs_fallback, pad_out[4];
} __attribute__((aligned(64)));

static unsigned int psp_mv_hash(unsigned int hash, void const *data, unsigned int bytes)
{
	unsigned char const *byte = (unsigned char const *)data;

	while (bytes--)
		hash = (hash ^ *byte++) * 16777619u;
	return hash;
}

/* an answer by its hashes: the visible clusters' bits, the rendered
clusters (index and clip bounds, in order), the environment's surfaces'
bits */
static void psp_mv_answer(struct render_globals const *view, unsigned int *clusters, unsigned int *cluster_hash,
	unsigned int *surfaces, unsigned int *surface_hash)
{
	struct structure_bsp *structure = global_structure_bsp_get();
	unsigned int hash = 2166136261u;
	short k;

	hash = psp_mv_hash(hash, view->visible_cluster_flags, BIT_VECTOR_SIZE_IN_BYTES(structure->clusters.count));
	for (k = 0; k < view->rendered_cluster_count; k++)
	{
		hash = psp_mv_hash(hash, &view->rendered_clusters[k].cluster_index, sizeof(view->rendered_clusters[k].cluster_index));
		hash = psp_mv_hash(hash, &view->rendered_clusters[k].clip_bounds, sizeof(view->rendered_clusters[k].clip_bounds));
	}
	*clusters = (unsigned int)view->rendered_cluster_count;
	*cluster_hash = hash;
	*surfaces = (unsigned int)view->environment_surface_count;
	/* (the PSP's subcluster walk marks the surfaces in the flags and counts
	them; the index list isn't written) */
	*surface_hash = psp_mv_hash(2166136261u, view->environment_surface_flags,
		BIT_VECTOR_SIZE_IN_BYTES(structure->surfaces.count));
}

static __inline__ unsigned int psp_mv_cycles(void)
{
	unsigned int count;

	__asm__ __volatile__("mfc0 %0, $9" : "=r"(count));
	return count;
}

/* fn(argument) on the stack ending at top (the copy's walk is deeper than
the ME's own stack in eDRAM has room for) */
void psp_mv_call_on(void (*fn)(void *), void *argument, void *top);
__asm__(
	"	.text\n"
	"	.globl psp_mv_call_on\n"
	"	.type psp_mv_call_on, @function\n"
	"	.set push\n"
	"	.set noreorder\n"
	"psp_mv_call_on:\n"
	"	addiu $a2, $a2, -32\n"
	"	sw $sp, 16($a2)\n"
	"	sw $ra, 20($a2)\n"
	"	move $sp, $a2\n"
	"	move $t9, $a0\n"
	"	jalr $t9\n"
	"	move $a0, $a1\n"
	"	lw $ra, 20($sp)\n"
	"	lw $sp, 16($sp)\n"
	"	jr $ra\n"
	"	nop\n"
	"	.set pop\n"
	"	.size psp_mv_call_on, .-psp_mv_call_on\n");

/* on the ME, on the copy's own stack */
static void psp_mv_run(void *argument)
{
	struct psp_mv_record *record = (struct psp_mv_record *)argument;
	unsigned int start, middle, end, clusters, cluster_hash, surfaces, surface_hash;
	short count;

	csmemcpy(&psp_mv->render, record->head, PSP_MV_HEAD_BYTES);
	psp_mv->visrect_mode = record->visrect_mode;
	psp_mv->depth = psp_mv->depth_most = 0;
	psp_mv->too_deep = 0;
	start = psp_mv_cycles();
	psp_mv_structure_visibility_compute();
	middle = psp_mv_cycles();
	csmemset(psp_mv->object_marks, 0, sizeof(psp_mv->object_marks));
	count = psp_mv_structure_visibility_find_objects(psp_mv->objects, MAXIMUM_RENDERED_OBJECTS,
		cluster_get_first_collideable_object, cluster_get_next_collideable_object,
		object_get_render_bounding_sphere, psp_mv_unmarked, psp_mv_mark);
	count += psp_mv_structure_visibility_find_objects(&psp_mv->objects[count], MAXIMUM_RENDERED_OBJECTS - count,
		cluster_get_first_noncollideable_object, cluster_get_next_noncollideable_object,
		object_get_render_bounding_sphere, psp_mv_unmarked, psp_mv_mark);
	end = psp_mv_cycles();
	psp_mv_answer(&psp_mv->render, &clusters, &cluster_hash, &surfaces, &surface_hash);
	record->clusters = clusters;
	record->cluster_hash = cluster_hash;
	record->surfaces = surfaces;
	record->surface_hash = surface_hash;
	record->objects = (unsigned int)count;
	record->object_hash = psp_mv_hash(2166136261u, psp_mv->objects, (unsigned int)count * sizeof(long));
	record->cycles_clusters = middle - start;
	record->cycles_objects = end - middle;
	record->depth_most = (unsigned int)psp_mv->depth_most;
	record->too_deep = (unsigned int)psp_mv->too_deep;
	record->pvs_fallback = psp_mv->pvs_fallback;
	if (psp_mv_edram)
	{
		/* what the main CPU reads, out of the eDRAM (above) */
		struct psp_mv_handed *out = psp_mv_handed;

		csmemcpy(out->visible_cluster_flags, psp_mv->render.visible_cluster_flags, sizeof(out->visible_cluster_flags));
		out->rendered_cluster_count = psp_mv->render.rendered_cluster_count;
		csmemcpy(out->rendered_clusters, psp_mv->render.rendered_clusters,
			(unsigned int)psp_mv->render.rendered_cluster_count * sizeof(out->rendered_clusters[0]));
		csmemcpy((void *)record->pad_in[1], psp_mv->render.environment_surface_flags, record->pad_in[2]);
		out->environment_surface_count = psp_mv->render.environment_surface_count;
		csmemcpy(out->objects, psp_mv->objects, (unsigned int)count * sizeof(long));
	}
	record->done = 1;
}

/* the ring job (psp_me.c, ME_JOB_VISIBILITY), on the ME: under the main
CPU's FPU control, as its own walk ran */
void psp_mevis_me_job(const unsigned int *args, unsigned int *results)
{
	struct psp_mv_record *record = (struct psp_mv_record *)args[0];
	unsigned int control = record->fpu_control, saved;

	unsigned int k;

	/* mevisedram: the eDRAM's state cleared and its stack filled here, by the
	ME, on the first job (and after the ME restarted: the main CPU asks) */
	if (psp_mv_edram && record->pad_in[0])
	{
		csmemset(psp_mv, 0, PSP_MV_STATE_BYTES);
		for (k = 0; k < PSP_MV_STACK / 4; k++)
			psp_mv_stack_bottom[k] = PSP_MV_CANARY;
	}
	__asm__ __volatile__("cfc1 %0, $31" : "=r"(saved));
	__asm__ __volatile__("ctc1 %0, $31" : : "r"(control));
	psp_mv_call_on(psp_mv_run, record, psp_mv_stack_top);
	__asm__ __volatile__("ctc1 %0, $31" : : "r"(saved));
	for (k = 0; k < PSP_MV_CANARY_WORDS; k++)
		if (psp_mv_stack_bottom[k] != PSP_MV_CANARY)
		{
			record->done = 0;
			record->pad_out[0] = 1;
			break;
		}
	if (psp_mv_edram)
	{
		/* the stack's lowest changed word, for the report (the main CPU
		can't look) */
		unsigned int low = 0;

		while (low < PSP_MV_STACK / 4 && psp_mv_stack_bottom[low] == PSP_MV_CANARY)
			low++;
		psp_mv_handed->stack_low = low;
	}
	results[0] = 1;
}

/* ---------- the main CPU's side: the push before its own visibility, its
answers, and the look at the frame's end */
int psp_keep(const char *name);
void platform_psp_log(const char *format, ...);
unsigned long psp_microseconds(void);
unsigned int sceKernelGetSystemTimeLow(void);
void sceKernelDcacheInvalidateRange(const void *p, unsigned int size);
void sceKernelDcacheWritebackRange(const void *p, unsigned int size);
void *memalign(size_t alignment, size_t size);
int psp_me_push_visibility(void *record, unsigned int record_bytes, unsigned int *ticket); /* psp_me.c */
int psp_me_ring_done(unsigned int ticket);
float psp_me_cycles_per_us(void);

static int psp_mv_on = -1, psp_mv_out = 0, psp_mv_pushed = 0, psp_mv_stuck = 0, psp_mv_have_clusters = 0, psp_mv_have_objects = 0;
static unsigned int psp_mv_ticket;
static struct psp_mv_record *psp_mv_record;
static unsigned int psp_mv_main_clusters, psp_mv_main_cluster_hash, psp_mv_main_surfaces, psp_mv_main_surface_hash;
static unsigned int psp_mv_main_object_count, psp_mv_main_object_hash;
static unsigned long psp_mv_frames, psp_mv_answers, psp_mv_late, psp_mv_wait_us, psp_mv_refused, psp_mv_differ_clusters,
	psp_mv_differ_objects, psp_mv_main_us_clusters, psp_mv_main_us_objects, psp_mv_main_views, psp_mv_too_deep,
	psp_mv_depth_most, psp_mv_pvs;
static unsigned long long psp_mv_cycles_clusters, psp_mv_cycles_objects, psp_mv_cycles_most;
static unsigned long psp_mv_differ_parts[4], psp_mv_differ_lines;

/* the surfaces' buffer (above) fitted to this BSP before a push: 0 when it
can't grow, and then the main CPU makes the view itself */
static int psp_mv_surfaces_fit(void)
{
	unsigned int bytes = BIT_VECTOR_SIZE_IN_BYTES(global_structure_bsp_get()->surfaces.count);
	unsigned long *grown;

	if (bytes > psp_mv_surface_bytes)
	{
		grown = (unsigned long *)memalign(64, (bytes + 63) & ~63u);
		if (!grown)
			return 0;
		/* the C library's free, as memalign's pair: cseries.h makes free()
		the engine's match_free, which read a header below a NULL at the
		first grow (mvbits1: all three maps faulted in psp_mv_surfaces_fit) */
		(free)(psp_mv_surface_flags);
		psp_mv_surface_flags = grown;
		psp_mv_surface_bytes = (bytes + 63) & ~63u;
		platform_psp_log("mevisedram: the surfaces' bits handed back grow to %u bytes", psp_mv_surface_bytes);
	}
	psp_mv_record->pad_in[1] = (unsigned int)psp_mv_surface_flags;
	psp_mv_record->pad_in[2] = bytes;
	return 1;
}

static int psp_mv_start(void)
{
	unsigned int state_bytes = PSP_MV_STATE_BYTES, k;
	void *stack;

	int psp_me_simulated(void); /* psp_me.c */
	int psp_me_sim_edram_holds(unsigned int offset, unsigned int bytes);

	/* mevisedram (above): the eDRAM's 0-192 KB, when the state fits under the
	stack. The emulator maps no eDRAM below 800 KB, so there the state and the
	stack stay on the heap, standing in, and only the main CPU's side (the
	answers through psp_mv_handed, the ME's own clear and look) is tried */
	psp_mv_edram = !psp_keep("mevisedramoff") && state_bytes <= PSP_MV_EDRAM_TOP - PSP_MV_STACK;
	if (psp_mv_edram)
	{
		if (!psp_me_simulated() || psp_me_sim_edram_holds(0, PSP_MV_EDRAM_TOP))
		{
			psp_mv = (struct psp_mv_state *)PSP_MV_ME_EDRAM;
			stack = (void *)(PSP_MV_ME_EDRAM + PSP_MV_EDRAM_TOP - PSP_MV_STACK);
		}
		else
		{
			psp_mv = (struct psp_mv_state *)memalign(64, state_bytes);
			stack = memalign(64, PSP_MV_STACK);
			platform_psp_log("mevisedram: the emulator maps no eDRAM at 0-%u KB: the state and the stack stand in on the heap",
				PSP_MV_EDRAM_TOP / 1024);
		}
		psp_mv_handed = (struct psp_mv_handed *)memalign(64, sizeof(struct psp_mv_handed));
	}
	else
	{
		psp_mv = (struct psp_mv_state *)memalign(64, state_bytes);
		stack = memalign(64, PSP_MV_STACK);
	}
	psp_mv_record = (struct psp_mv_record *)memalign(64, sizeof(struct psp_mv_record));
	if (!psp_mv || !stack || !psp_mv_record || (psp_mv_edram && !psp_mv_handed))
	{
		platform_psp_log("mevis: no room for the ME's copy (%u KB state, %u KB stack); off", state_bytes / 1024,
			PSP_MV_STACK / 1024);
		return 0;
	}
	csmemset(psp_mv_record, 0, sizeof(*psp_mv_record));
	psp_mv_stack_top = (char *)stack + PSP_MV_STACK;
	psp_mv_stack_bottom = (unsigned int *)stack;
	if (psp_mv_edram)
	{
		/* the ME clears the state and fills the stack at its first job */
		csmemset(psp_mv_handed, 0, sizeof(*psp_mv_handed));
		psp_mv_record->pad_in[0] = 1;
		platform_psp_log("mevisedram: the ME's state (%u KB) and stack (%u KB) in its eDRAM at 0-%u KB; %u KB of answers in main RAM",
			state_bytes / 1024, PSP_MV_STACK / 1024, PSP_MV_EDRAM_TOP / 1024, (unsigned int)sizeof(struct psp_mv_handed) / 1024);
	}
	else
	{
		csmemset(psp_mv, 0, state_bytes);
		/* the whole stack, so the report can say how deep the walks reached
		(the lowest word changed); the walk's check reads only the bottom */
		for (k = 0; k < PSP_MV_STACK / 4; k++)
			psp_mv_stack_bottom[k] = PSP_MV_CANARY;
	}
	platform_psp_log("mevis: the frame's visibility again on the ME, timed and checked (%u KB state, %u KB stack, %d clusters deep at most)",
		state_bytes / 1024, PSP_MV_STACK / 1024, PSP_MV_DEPTH);
	return 1;
}

/* render.c, before the frame's first structure_visibility_compute */
void psp_mevis_view_begin(void)
{
	unsigned int control;

	if (psp_mv_on < 0)
		psp_mv_on = psp_keep("mevis") ? psp_mv_start() : 0;
	if (!psp_mv_on || psp_mv_pushed || psp_mv_out || psp_mv_stuck)
		return;
	psp_mv_pushed = 1;
	csmemcpy(psp_mv_record->head, &render, PSP_MV_HEAD_BYTES);
	psp_mv_record->visrect_mode = psp_keep("visrectcheck") ? 2 : psp_keep("visrectold") || psp_keep("smallwins2old") ? 0 : 1;
	__asm__ __volatile__("cfc1 %0, $31" : "=r"(control));
	psp_mv_record->fpu_control = control;
	psp_mv_record->done = 0;
	if (psp_mv_edram && !psp_mv_surfaces_fit())
		psp_mv_refused++;
	else if (psp_me_push_visibility(psp_mv_record, sizeof(*psp_mv_record), &psp_mv_ticket))
		psp_mv_out = 1;
	else
		psp_mv_refused++;
}

/* render.c, after it: the main CPU's answer and its time */
void psp_mevis_main_clusters(unsigned long us)
{
	if (!psp_mv_on || !psp_mv_pushed || psp_mv_have_clusters)
		return;
	psp_mv_have_clusters = 1;
	psp_mv_main_us_clusters += us;
	psp_mv_answer(&render, &psp_mv_main_clusters, &psp_mv_main_cluster_hash, &psp_mv_main_surfaces, &psp_mv_main_surface_hash);
}

/* render_objects.c's find_rendered_objects */
void psp_mevis_main_objects(long const *indices, short count, unsigned long us)
{
	if (!psp_mv_on || !psp_mv_pushed || psp_mv_have_objects)
		return;
	psp_mv_have_objects = 1;
	psp_mv_main_us_objects += us;
	psp_mv_main_object_count = (unsigned int)count;
	psp_mv_main_object_hash = psp_mv_hash(2166136261u, indices, (unsigned int)count * sizeof(long));
}

/* render.c, at render_frame's end: the ME's answer, waited for (at most
100 ms: the tick that follows changes what the job reads), compared */
void psp_mevis_frame_end(void)
{
	if (psp_mv_on <= 0)
		return;
	if (psp_mv_out)
	{
		unsigned int start = sceKernelGetSystemTimeLow();
		int done = psp_me_ring_done(psp_mv_ticket);

		if (!done)
		{
			psp_mv_late++;
			while (!(done = psp_me_ring_done(psp_mv_ticket)) && sceKernelGetSystemTimeLow() - start < 100000)
				;
			psp_mv_wait_us += sceKernelGetSystemTimeLow() - start;
		}
		if (!done)
		{
			psp_mv_stuck = 1;
			platform_psp_log("mevis: the ME's visibility not done 100 ms after the frame's end; no more pushed");
		}
		else
		{
			unsigned long long both;

			sceKernelDcacheInvalidateRange(psp_mv_record, sizeof(*psp_mv_record));
			psp_mv_out = 0;
			if (psp_mv_record->done)
			{
				psp_mv_answers++;
				psp_mv_cycles_clusters += psp_mv_record->cycles_clusters;
				psp_mv_cycles_objects += psp_mv_record->cycles_objects;
				both = (unsigned long long)psp_mv_record->cycles_clusters + psp_mv_record->cycles_objects;
				if (both > psp_mv_cycles_most)
					psp_mv_cycles_most = both;
				psp_mv_too_deep += psp_mv_record->too_deep;
				psp_mv_pvs += psp_mv_record->pvs_fallback;
				if (psp_mv_record->depth_most > psp_mv_depth_most)
					psp_mv_depth_most = psp_mv_record->depth_most;
				if (psp_mv_have_clusters && (psp_mv_record->clusters != psp_mv_main_clusters ||
					psp_mv_record->cluster_hash != psp_mv_main_cluster_hash || psp_mv_record->surfaces != psp_mv_main_surfaces ||
					psp_mv_record->surface_hash != psp_mv_main_surface_hash))
				{
					psp_mv_differ_clusters++;
					psp_mv_differ_parts[0] += psp_mv_record->clusters != psp_mv_main_clusters;
					psp_mv_differ_parts[1] += psp_mv_record->cluster_hash != psp_mv_main_cluster_hash;
					psp_mv_differ_parts[2] += psp_mv_record->surfaces != psp_mv_main_surfaces;
					psp_mv_differ_parts[3] += psp_mv_record->surface_hash != psp_mv_main_surface_hash;
					if (psp_mv_differ_lines < 8)
					{
						psp_mv_differ_lines++;
						platform_psp_log("mevis: differs: clusters %u here, %u on the ME (bits and bounds %08x, %08x); surfaces %u, %u (%08x, %08x)",
							psp_mv_main_clusters, psp_mv_record->clusters, psp_mv_main_cluster_hash, psp_mv_record->cluster_hash,
							psp_mv_main_surfaces, psp_mv_record->surfaces, psp_mv_main_surface_hash, psp_mv_record->surface_hash);
					}
				}
				if (psp_mv_have_objects && (psp_mv_record->objects != psp_mv_main_object_count ||
					psp_mv_record->object_hash != psp_mv_main_object_hash))
					psp_mv_differ_objects++;
				if (psp_mv_have_clusters)
					psp_mv_main_views++;
			}
		}
	}
	psp_mv_pushed = psp_mv_have_clusters = psp_mv_have_objects = 0;
	if (++psp_mv_frames % 300 == 0)
	{
		float per_us = psp_me_cycles_per_us();
		double answers = psp_mv_answers ? (double)psp_mv_answers : 1.0, views = psp_mv_main_views ? (double)psp_mv_main_views : 1.0;

		platform_psp_log("mevis: %lu answers from the ME in %lu frames: on the ME %.2f ms a frame (clusters %.2f + objects %.2f, the most %.2f), here %.2f ms (clusters %.2f + objects %.2f); not done by the frame's end %lu (waited %.2f ms a frame); differing from here: clusters %lu, objects %lu; cut at %d clusters deep %lu times (the deepest %lu); portal walks over budget %lu; not taken by the ring %lu; of the clusters' differences: count %lu, bits and bounds %lu, surface count %lu, surfaces %lu; the ME's clock %.1f cycles a us (last 300 frames)",
			psp_mv_answers, psp_mv_frames,
			per_us > 0.0f ? (psp_mv_cycles_clusters + psp_mv_cycles_objects) / per_us / 1000.0 / answers : 0.0,
			per_us > 0.0f ? psp_mv_cycles_clusters / per_us / 1000.0 / answers : 0.0,
			per_us > 0.0f ? psp_mv_cycles_objects / per_us / 1000.0 / answers : 0.0,
			per_us > 0.0f ? psp_mv_cycles_most / per_us / 1000.0 : 0.0,
			(psp_mv_main_us_clusters + psp_mv_main_us_objects) / 1000.0 / views,
			psp_mv_main_us_clusters / 1000.0 / views, psp_mv_main_us_objects / 1000.0 / views,
			psp_mv_late, psp_mv_wait_us / 1000.0 / 300.0, psp_mv_differ_clusters, psp_mv_differ_objects,
			PSP_MV_DEPTH, psp_mv_too_deep, psp_mv_depth_most, psp_mv_pvs, psp_mv_refused, psp_mv_differ_parts[0],
			psp_mv_differ_parts[1], psp_mv_differ_parts[2], psp_mv_differ_parts[3], (double)per_us);
		csmemset(psp_mv_differ_parts, 0, sizeof(psp_mv_differ_parts));
		psp_mv_frames = psp_mv_answers = psp_mv_late = psp_mv_wait_us = psp_mv_refused = psp_mv_differ_clusters = 0;
		psp_mv_differ_objects = psp_mv_main_us_clusters = psp_mv_main_us_objects = psp_mv_main_views = psp_mv_too_deep = 0;
		psp_mv_depth_most = psp_mv_pvs = 0;
		psp_mv_cycles_clusters = psp_mv_cycles_objects = psp_mv_cycles_most = 0;
	}
}
/* ---------- "mevisland" (docs/mevis_landing.md): the frame's visibility made
on the ME and used. It is pushed where the main CPU's own would run
(structure_visibility_compute) and collected at its first reader
(lights_preprocess_scene). No tick runs between, and nothing the main CPU does
in that span writes what visibility reads, so the answer is the main CPU's, bit
for bit. A push the ring refuses, or an answer later than PSP_ML_LATE_US,
has the main CPU make its own visibility there: the safety net, as before */
#define PSP_ML_LATE_US 50000
int psp_me_push_visibility_into(void *record, void *answer, unsigned int answer_bytes, unsigned int *ticket); /* psp_me.c */
void psp_me_ring_collected(unsigned int ticket); /* psp_me.c: mevisring */

static int psp_ml_on = -1, psp_ml_check = 0, psp_ml_out = 0, psp_ml_waiting = 0, psp_ml_objects_ready = 0, psp_ml_overran = 0;
/* where the walk runs is decided by measurement (CLAUDE.md, placement): the
ME's walk pays only while the main CPU has enough of its own to do before
the first reader. Each view made here is timed (psp_ml_main_avg) and each
answer's wait at the first reader too (psp_ml_wait_avg, eighths of a us,
both moving averages). When the wait comes within PSP_ML_MARGIN_US of the
walk itself, the next PSP_ML_REST views are made here, which also refreshes
the walk's time, then the ME is tried again; a long run of pushes rests for
PSP_ML_REFRESH views now and then to keep that time current. The walk's time
is only refreshed while views are made here, so by the time a check comes it
may be from another stretch (a cheap landing before a heavy beach): with
"mevisprobe" (on by default) a rest is weighed again every PSP_ML_REFRESH
views on the walk's fresh time, against the wait that called for it, and
ends as soon as that time no longer calls for one. "mevislandalways" pushes every view (the A/B's other side). The ME's time isn't free either (its
own frame's replay waits behind the walk, and the bus is shared with the
tick), so a walk under PSP_ML_MIN_WALK_US stays here: there's little to win */
#define PSP_ML_MARGIN_US 500
#define PSP_ML_MIN_WALK_US 1500
#define PSP_ML_CHECK 32
#define PSP_ML_REST 240
#define PSP_ML_PUSHES_BEFORE_REFRESH 600
#define PSP_ML_REFRESH 16
static int psp_ml_always = 0, psp_ml_rest = PSP_ML_CHECK, psp_ml_since_check = 0, psp_ml_since_refresh = 0;
static int psp_ml_probe = 0, psp_ml_rest_weighed = 0;
static unsigned long psp_ml_main_avg = 0, psp_ml_wait_avg = 0, psp_ml_here = 0, psp_ml_rests = 0, psp_ml_probes_back = 0;
static unsigned long psp_ml_rest_wait = 0;

/* the test that calls for a rest: the ME's answer waited (wait_avg) for nearly
as long as the walk takes here, or a walk too short to be worth the ME's time */
static int psp_ml_rest_called(unsigned long wait_avg)
{
	return wait_avg / 8 + PSP_ML_MARGIN_US >= psp_ml_main_avg / 8 || psp_ml_main_avg / 8 < PSP_ML_MIN_WALK_US;
}
static unsigned long psp_ml_depth_most = 0, psp_ml_too_deep = 0;
static unsigned int psp_ml_ticket, psp_ml_state_bytes;
static unsigned long psp_ml_views, psp_ml_used, psp_ml_refused, psp_ml_busy, psp_ml_late, psp_ml_failed, psp_ml_wait_us,
	psp_ml_wait_worst, psp_ml_waited, psp_ml_differ_clusters, psp_ml_differ_objects;

/* this CPU's copies of lines the ME wrote, dropped before they are read. It
never writes the copies' state or the record after the push (the push writes
its whole cache back first), so dropping loses nothing of its own */
static void psp_ml_drop(void const *p, unsigned int bytes)
{
	unsigned int start = (unsigned int)p & ~63u, end = ((unsigned int)p + bytes + 63u) & ~63u;

	sceKernelDcacheInvalidateRange((void const *)start, end - start);
}

/* render.c's render_window, in place of structure_visibility_compute: 1 when
the ME makes it, 0 when the main CPU should, now */
int psp_mevisland_push(void)
{
	unsigned int control;

	if (psp_ml_on < 0)
	{
		psp_ml_on = psp_keep("mevisland") ? (psp_mv != NULL || psp_mv_start()) : 0;
		psp_ml_check = psp_ml_on && psp_keep("mevislandcheck");
		psp_ml_always = psp_ml_on && (psp_keep("mevislandalways") || psp_ml_check);
		psp_ml_probe = psp_ml_on && psp_keep("mevisprobe");
		psp_ml_state_bytes = PSP_MV_STATE_BYTES;
		if (psp_ml_on)
			platform_psp_log("mevisland: the frame's visibility made on the ME and used%s",
				psp_ml_check ? "; mevislandcheck: the main CPU makes its own too, and the two are compared" : "");
	}
	if (!psp_ml_on || psp_ml_overran)
		return 0;
	psp_ml_views++;
	if (psp_ml_out)
	{
		/* an earlier answer, too late to be used, still being made: the
		copies' state is the ME's until it ends */
		if (!psp_me_ring_done(psp_ml_ticket))
		{
			psp_ml_busy++;
			return 0;
		}
		psp_me_ring_collected(psp_ml_ticket);
		psp_ml_out = 0;
	}
	/* (a structure the port can't hold: the main CPU's own path, which
	clears what it can) */
	if (!structure_bsp_port_verify(global_structure_bsp_get()))
		return 0;
	if (!psp_ml_always && psp_ml_rest > 0)
	{
		unsigned int start = sceKernelGetSystemTimeLow(), took;

		psp_ml_rest--;
		psp_ml_here++;
		structure_visibility_compute();
		took = sceKernelGetSystemTimeLow() - start;
		psp_ml_main_avg = psp_ml_main_avg ? (psp_ml_main_avg * 7 + took * 8) / 8 : took * 8;
		if (psp_ml_rest_weighed && psp_ml_rest > 0 && (PSP_ML_REST - psp_ml_rest) % PSP_ML_REFRESH == 0 &&
			!psp_ml_rest_called(psp_ml_rest_wait))
		{
			psp_ml_rest = 0;
			psp_ml_probes_back++;
		}
		return 1;
	}
	csmemcpy(psp_mv_record->head, &render, PSP_MV_HEAD_BYTES);
	psp_mv_record->visrect_mode = psp_keep("visrectcheck") ? 2 : psp_keep("visrectold") || psp_keep("smallwins2old") ? 0 : 1;
	__asm__ __volatile__("cfc1 %0, $31" : "=r"(control));
	psp_mv_record->fpu_control = control;
	psp_mv_record->done = 0;
	if (psp_mv_edram)
	{
		/* an ME restarted (a sleep) left the eDRAM as it found it: clear it again */
		extern volatile unsigned int psp_me_stops; /* psp_me.c */
		static unsigned int stops_seen;

		if (psp_me_stops != stops_seen)
		{
			stops_seen = psp_me_stops;
			psp_mv_record->pad_in[0] = 1;
		}
		if (!psp_mv_surfaces_fit())
		{
			psp_ml_refused++;
			return 0;
		}
	}
	if (!psp_me_push_visibility_into(psp_mv_record, psp_mv_edram ? (void *)psp_mv_handed : (void *)psp_mv,
		psp_mv_edram ? (unsigned int)sizeof(struct psp_mv_handed) : psp_ml_state_bytes, &psp_ml_ticket))
	{
		psp_ml_refused++;
		return 0;
	}
	psp_ml_out = psp_ml_waiting = 1;
	return 1;
}

/* render.c, before lights_preprocess_scene (and at the window's end, for a
view that never reached it): the ME's clusters and surfaces copied in, the
fields structure_visibility_compute writes, or the main CPU's own made now */
void psp_mevisland_collect(void)
{
	struct structure_bsp *structure;
	unsigned int start, waited;
	int done;

	if (!psp_ml_waiting)
		return;
	psp_ml_waiting = 0;
	start = sceKernelGetSystemTimeLow();
	done = psp_me_ring_done(psp_ml_ticket);
	while (!done && sceKernelGetSystemTimeLow() - start < PSP_ML_LATE_US)
		done = psp_me_ring_done(psp_ml_ticket);
	waited = sceKernelGetSystemTimeLow() - start;
	psp_ml_wait_us += waited;
	if (waited > psp_ml_wait_worst)
		psp_ml_wait_worst = waited;
	psp_ml_waited += waited > 0;
	if (!done)
	{
		psp_ml_late++;
		structure_visibility_compute();
		return;
	}
	psp_me_ring_collected(psp_ml_ticket);
	psp_ml_out = 0;
	psp_ml_drop(psp_mv_record, sizeof(*psp_mv_record));
	if (psp_mv_record->depth_most > psp_ml_depth_most)
		psp_ml_depth_most = psp_mv_record->depth_most;
	if (!psp_mv_record->done || psp_mv_record->too_deep)
	{
		/* a walk cut at PSP_MV_DEPTH, or one that ran past its stack: not
		the main CPU's answer */
		psp_ml_failed++;
		psp_ml_too_deep += psp_mv_record->too_deep != 0;
		if (psp_mv_record->pad_out[0] && !psp_ml_overran)
		{
			psp_ml_overran = 1;
			platform_psp_log("mevisland: the ME's walk ran past its %u KB stack; its answers are made here from now on",
				PSP_MV_STACK / 1024);
		}
		structure_visibility_compute();
		return;
	}
	structure = global_structure_bsp_get();
	if (psp_mv_edram)
	{
		psp_mv_record->pad_in[0] = 0;
		psp_ml_drop(psp_mv_handed, sizeof(*psp_mv_handed));
		psp_ml_drop(psp_mv_surface_flags, psp_mv_record->pad_in[2]);
	}
	else
	{
		psp_ml_drop(&psp_mv->render, PSP_MV_RENDER_BYTES);
		psp_ml_drop(psp_mv->objects, sizeof(psp_mv->objects));
	}
	if (psp_ml_check)
	{
		unsigned int clusters, cluster_hash, surfaces, surface_hash;

		structure_visibility_compute();
		psp_mv_answer(&render, &clusters, &cluster_hash, &surfaces, &surface_hash);
		psp_ml_differ_clusters += clusters != psp_mv_record->clusters || cluster_hash != psp_mv_record->cluster_hash ||
			surfaces != psp_mv_record->surfaces || surface_hash != psp_mv_record->surface_hash;
	}
	if (psp_mv_edram)
	{
		csmemcpy(render.visible_cluster_flags, psp_mv_handed->visible_cluster_flags,
			BIT_VECTOR_SIZE_IN_BYTES(structure->clusters.count));
		render.rendered_cluster_count = psp_mv_handed->rendered_cluster_count;
		csmemcpy(render.rendered_clusters, psp_mv_handed->rendered_clusters,
			render.rendered_cluster_count * sizeof(render.rendered_clusters[0]));
		csmemcpy(render.environment_surface_flags, psp_mv_surface_flags, psp_mv_record->pad_in[2]);
		render.environment_surface_count = psp_mv_handed->environment_surface_count;
	}
	else
	{
		csmemcpy(render.visible_cluster_flags, psp_mv->render.visible_cluster_flags,
			BIT_VECTOR_SIZE_IN_BYTES(structure->clusters.count));
		render.rendered_cluster_count = psp_mv->render.rendered_cluster_count;
		csmemcpy(render.rendered_clusters, psp_mv->render.rendered_clusters,
			render.rendered_cluster_count * sizeof(render.rendered_clusters[0]));
		csmemcpy(render.environment_surface_flags, psp_mv->render.environment_surface_flags,
			BIT_VECTOR_SIZE_IN_BYTES(structure->surfaces.count));
		render.environment_surface_count = psp_mv->render.environment_surface_count;
	}
	psp_pvs_fallback = (boolean)psp_mv_record->pvs_fallback;
	psp_ml_objects_ready = 1;
	psp_ml_used++;
	psp_ml_wait_avg = psp_ml_wait_avg ? (psp_ml_wait_avg * 7 + waited * 8) / 8 : waited * 8;
	if (!psp_ml_always && ++psp_ml_since_check >= PSP_ML_CHECK)
	{
		psp_ml_since_check = 0;
		if (psp_ml_rest_called(psp_ml_wait_avg))
		{
			psp_ml_rest = PSP_ML_REST;
			psp_ml_rests++;
			psp_ml_rest_wait = psp_ml_wait_avg;
			psp_ml_rest_weighed = psp_ml_probe;
			psp_ml_wait_avg = 0;
			psp_ml_since_refresh = 0;
		}
	}
	if (!psp_ml_always && ++psp_ml_since_refresh >= PSP_ML_PUSHES_BEFORE_REFRESH)
	{
		psp_ml_since_refresh = 0;
		psp_ml_rest = PSP_ML_REFRESH;
		psp_ml_rest_weighed = 0;
	}
}

/* render_objects.c's find_rendered_objects: the ME's list, and the marks the
main CPU's walk would have left on the objects it listed (only those: an
object is marked as it is listed) */
int psp_mevisland_objects(long *indices, short *count)
{
	short k, n;

	if (!psp_ml_objects_ready)
		return 0;
	psp_ml_objects_ready = 0;
	n = (short)psp_mv_record->objects;
	if (psp_ml_check)
	{
		/* the main CPU's own walk, which leaves its marks */
		short mine;

		object_marker_begin();
		mine = structure_visibility_find_objects(indices, MAXIMUM_RENDERED_OBJECTS, cluster_get_first_collideable_object,
			cluster_get_next_collideable_object, object_get_render_bounding_sphere, object_unmarked_function, object_mark_function);
		mine += structure_visibility_find_objects(&indices[mine], MAXIMUM_RENDERED_OBJECTS - mine,
			cluster_get_first_noncollideable_object, cluster_get_next_noncollideable_object, object_get_render_bounding_sphere,
			object_unmarked_function, object_mark_function);
		object_marker_end();
		psp_ml_differ_objects += mine != n || psp_mv_hash(2166136261u, indices, (unsigned int)mine * sizeof(long)) !=
			psp_mv_record->object_hash;
		csmemcpy(indices, psp_mv_edram ? psp_mv_handed->objects : psp_mv->objects, (unsigned int)n * sizeof(long));
		*count = n;
		return 1;
	}
	csmemcpy(indices, psp_mv_edram ? psp_mv_handed->objects : psp_mv->objects, (unsigned int)n * sizeof(long));
	object_marker_begin();
	for (k = 0; k < n; k++)
		object_mark_function(indices[k]);
	object_marker_end();
	*count = n;
	return 1;
}

/* render.c, at the window's end */
void psp_mevisland_settle(void)
{
	if (psp_ml_on <= 0)
		return;
	psp_mevisland_collect();
	psp_ml_objects_ready = 0;
	if (psp_ml_views >= 300)
	{
		unsigned int low = 0;

		/* the stack's lowest changed word (the ME wrote it; this CPU never
		does, so its lines are dropped before the look) */
		if (psp_mv_edram)
			low = psp_mv_handed->stack_low; /* the ME's own look (psp_mevis_me_job) */
		else if (!psp_ml_out)
		{
			psp_ml_drop(psp_mv_stack_bottom, PSP_MV_STACK);
			while (low < PSP_MV_STACK / 4 && psp_mv_stack_bottom[low] == PSP_MV_CANARY)
				low++;
		}
		platform_psp_log("mevisland: %lu views: the ME's answer used %lu; made here instead: refused by the ring %lu, the ME still on an earlier one %lu, late %lu, failed %lu (%lu cut at %d clusters deep); waited at the first reader %.2f ms a view (%lu views waited, the most %.2f ms); the deepest walk %lu clusters; the stack used %u of %u KB at most (since the start); made here by placement %lu (%lu rests, %lu of them ended early on the walk's fresh time; the walk here %.2f ms, the wait for the ME's %.2f ms, moving averages)%s (last 300 views)",
			psp_ml_views, psp_ml_used, psp_ml_refused, psp_ml_busy, psp_ml_late, psp_ml_failed, psp_ml_too_deep, PSP_MV_DEPTH,
			psp_ml_wait_us / 1000.0 / psp_ml_views, psp_ml_waited, psp_ml_wait_worst / 1000.0, psp_ml_depth_most,
			low ? (PSP_MV_STACK - low * 4) / 1024 : 0, PSP_MV_STACK / 1024, psp_ml_here, psp_ml_rests, psp_ml_probes_back,
			psp_ml_main_avg / 8000.0, psp_ml_wait_avg / 8000.0, psp_ml_always ? "; mevislandalways: every view pushed" : "");
		if (psp_ml_check)
			platform_psp_log("mevislandcheck: differing from the main CPU's own: clusters %lu, objects %lu (last 300 views)",
				psp_ml_differ_clusters, psp_ml_differ_objects);
		psp_ml_views = psp_ml_used = psp_ml_refused = psp_ml_busy = psp_ml_late = psp_ml_failed = 0;
		psp_ml_wait_us = psp_ml_wait_worst = psp_ml_waited = psp_ml_differ_clusters = psp_ml_differ_objects = 0;
		psp_ml_depth_most = psp_ml_too_deep = psp_ml_here = psp_ml_rests = psp_ml_probes_back = 0;
	}
}

/* ---------- "mevispush" (docs/mevis_slice2.md): the frame's sound_render made
right after the first view's visibility push, so the main CPU spends it while
the ME walks. main_game_render leaves it owed; render_window makes it after its
push (once a frame); main_game_render makes it at its end if no window took
it */
void sound_render(void); /* sound_manager.c */

static int psp_mp_on = -1, psp_mp_owed = 0;
static unsigned long psp_mp_frames = 0, psp_mp_in_window = 0, psp_mp_at_end = 0;

/* main.c's main_game_render, in place of sound_render: 1 when it is left owed */
int psp_mevispush_defer(void)
{
	if (psp_mp_on < 0)
	{
		psp_mp_on = psp_keep("mevispush");
		if (psp_mp_on)
			platform_psp_log("mevispush: the frame's sound made after the first view's visibility push");
	}
	if (!psp_mp_on)
		return 0;
	psp_mp_owed = 1;
	return 1;
}

/* render.c's render_window after the push (in_window 1), and main_game_render's
end (0): the owed sound_render, once */
void psp_mevispush_sound(int in_window)
{
	if (!psp_mp_owed)
		return;
	psp_mp_owed = 0;
	sound_render();
	if (in_window)
		psp_mp_in_window++;
	else
		psp_mp_at_end++;
	if (++psp_mp_frames >= 300)
	{
		platform_psp_log("mevispush: %lu frames: the sound made after the visibility push %lu, owed to the frame's end %lu (last 300 frames)",
			psp_mp_frames, psp_mp_in_window, psp_mp_at_end);
		psp_mp_frames = psp_mp_in_window = psp_mp_at_end = 0;
	}
}
"""


# An anchor inside a block the PSP never compiles changes nothing that runs:
# TICKCACHE's matched inside `#ifdef HALO_64BIT` and built a lever that did
# nothing. The blocks around each match are read (#if/#ifdef/#ifndef/#elif/
# #else/#endif, nested) and a match under one that names a macro the PSP
# build never sets, or `#if 0`, is named. A heuristic: `#if` expressions are
# judged by the names in them, not evaluated
OFF_MACROS = {"HALO_64BIT", "_WIN32", "_WIN64", "_MSC_VER", "__APPLE__", "__linux__", "__x86_64__", "HALO_GL"}
PREPROCESSOR_LINE = re.compile(r"^[ \t]*#[ \t]*(if|ifdef|ifndef|elif|else|endif)\b(.*)$", re.M)

def dead_block(text, at):
    """the condition of a block around offset `at` the PSP never compiles, or None"""
    stack = []   # (the condition, whether the block is off)
    for m in PREPROCESSOR_LINE.finditer(text, 0, at):
        word, rest = m.group(1), m.group(2).split("//")[0].split("/*")[0].strip()
        if word in ("if", "ifdef", "ifndef"):
            names = set(re.findall(r"[A-Za-z_][A-Za-z0-9_]*", rest)) - {"defined"}
            if word == "ifdef":
                off = rest in OFF_MACROS
            elif word == "ifndef":
                off = False
            else:
                off = rest == "0" or bool(names & OFF_MACROS) and "!" not in rest and "||" not in rest
            stack.append(("#%s %s" % (word, rest), off))
        elif word == "elif" and stack:
            names = set(re.findall(r"[A-Za-z_][A-Za-z0-9_]*", rest)) - {"defined"}
            stack[-1] = ("#elif %s" % rest, rest == "0" or bool(names & OFF_MACROS) and "!" not in rest and "||" not in rest)
        elif word == "else" and stack:
            cond, off = stack[-1]
            # the #else of a block that names an off macro is the PSP's
            stack[-1] = ("#else of %s" % cond, False if off else cond.startswith("#ifndef") and cond.split()[1] in OFF_MACROS)
        elif word == "endif" and stack:
            stack.pop()
    for cond, off in stack:
        if off:
            return cond
    return None

# The units only the multiplayer build compiles (psp_build.py's
# MULTIPLAYER_UNITS and INTERNET_UNITS). While multiplayer is left out (Sheepdog01,
# 2026-10-21), a campaign build reports their anchors that no longer match
# and goes on: their fixups were carried across the v0.9.0d pin unported, to
# be reconciled with the multiplayer build (docs/chupa_rebase.md, "v0.9.0d")
MULTIPLAYER_ONLY = ("source/networking/", "source/bungie_net/", "source/game/game_engine_",
                    "port/linux/game/network_", "port/linux/game/coop_", "port/linux/src/xnet.c",
                    "port/linux/src/p2p")
CARRY_MULTIPLAYER = os.environ.get("PSP_MULTIPLAYER", "") != "1"
# ChupathingyCE's perf log (port/linux/include/halo_perf_log.h, from the
# v0.9.1 test build) times the parts of the tick (game.c), physics and
# objects.c's update loop with HALO_PERF_BEGIN / END / COUNT statements. The PSP never
# defines HALO_PERF_LOG (nor HALO_CONSOLE_GL_LAYER, which turns it on), so
# each is ((void)0): in the files named here those statement lines, and the
# include that serves them, are taken out before the anchors are matched,
# which leaves the update loop's text as the PSP's fixups know it
# (none of them is the lone body of an if or a loop: checked at 6eef2f3)
PERF_STRIP = ("source/objects/objects.c", "source/game/game.c", "source/physics/physics.c")
PERF_LINE = re.compile(r'^[ \t]*(HALO_PERF_(BEGIN|END|COUNT)\([^;\n]*\);|#include "halo_perf_log\.h"[^\n]*)\n', re.M)
carried = []
dead_anchors = []
failures = []
for rel, changes in FIXES.items():
    path = os.path.join(TREE, rel)
    text = open(path, errors="surrogateescape").read()
    if "psp_fixups.py" in text:
        continue
    if rel in PERF_STRIP:
        text = PERF_LINE.sub("", text)
    applied = 0
    for change in changes:
        applied += 1
        old, new = change
        count = text.count(old)
        if count != 1 and CARRY_MULTIPLAYER and rel.startswith(MULTIPLAYER_ONLY) and rel != "source/bungie_net/common/thread_win32.c":
            carried.append(rel)
            continue
        if count != 1:
            failures.append("psp_fixups: %s: expected 1 match, found %d:\n%s" % (rel, count, old[:200]))
            if not CHECK_ONLY:
                sys.exit(failures[-1])
            continue
        dead = dead_block(text, text.index(old))
        if dead:
            dead_anchors.append("psp_fixups: warning: %s: an anchor matches only inside %s, which the PSP doesn't "
                                "compile:\n%s" % (rel, dead, old[:200]))
        text = text.replace(old, new)
    if not applied:
        # (a file with no changes left is left as it is; with
        # PSP_FIXUPS_CHECK=1 the mirror is still written, so the passes'
        # counts below are checked on the fixed text)
        continue
    # PSP_FRAMEPTR=0 builds every engine unit without the frame pointer, so
    # the lookups' own omit-frame-pointer attribute says nothing more. Left
    # in, it gives each its own optimisation settings, which -fprofile-use
    # and -fprofile-generate fill in differently: their callers were inlined
    # differently in the counting build and lost their counts
    if not FRAMEPTR:
        text = text.replace(' __attribute__((optimize("omit-frame-pointer")))', "")
    # the sizes go after the file's first #include, so its headers come first
    if rel.endswith(".h"):
        open(path, "w", errors="surrogateescape").write(text); continue
    first = text.index("#include")
    line_end = text.index("\n", first) + 1
    text = text[:line_end] + PRELUDE + text[line_end:]
    open(path, "w", errors="surrogateescape").write(text)
for line in dead_anchors:
    print(line)
if carried:
    print("psp_fixups: warning: %d anchors in multiplayer-only units carried unmatched (a campaign build doesn't compile them): %s"
          % (len(carried), ", ".join("%s x%d" % (rel, carried.count(rel)) for rel in sorted(set(carried)))))
if CHECK_ONLY:
    print("\n\n".join(failures))
# (before the passes below, which label and append: the copies are made from
# the fixed text alone)
if WALKAPART or MEVISLAND:
    print("psp_fixups: mevis's copies of %d visibility functions" % mevis_copies(TREE))
print("psp_fixups: %d files changed, AI debug records shared in %d, unaligned accesses fixed in %d, breadcrumbs in %d, code appended to %d, passes skipped in %d, packed designators %d"
      % (len(FIXES), ai_debug_records(TREE), unaligned_accesses(TREE), breadcrumbs(TREE) + step_labels(TREE), appended(TREE), skipped_passes(TREE), packed_designators(TREE)))
# build 102: after ai_debug_records, which skips a file once PSP_DEBUG_INDEX is in it
print("psp_fixups: AI debugger state on demand in %d files" % ai_debug_shrink(TREE))
print("psp_fixups: colour conversions in single precision in %d files" % float_colours(TREE))
print("psp_fixups: render interpolation for one local player in %d files" % interpolation_players(TREE))
print("psp_fixups: the settings' help text left out in %d rows (CONFIGHELP)" % config_help(TREE))
print("psp_fixups: the GL renderer compiled out in %d files" % gl_never(TREE))
print("psp_fixups: the collision user stack %s in %d files (COLLUSERS)" % ("shared, as before," if COLLUSERS_SHARED else "one a CPU (debug tools) or none", collision_users(TREE)))
print("psp_fixups: the AI's meters and ballistic record the main CPU's alone in %d files (AIMETERS)" % ai_meters(TREE))
print("psp_fixups: biped motion's window (intent to tail) through the store, %d datum accesses (BIPEDMOVE)" % biped_move_store(TREE))
print("psp_fixups: the typed getters' words forgotten at %d settings of the tag instance table (TAGMEMO)" % tag_memo_forgets(TREE))

# PSP_TICK2=1: the tick rewrite's count (slice 0; the lab's tick_rewrite_plan,
# docs/box_world_store.md section 13). The fields the world store will own
# for bipeds lose their names in the engine's datum structs, so every old
# line that touches one fails to compile, and the compiler's errors are the
# list of what the rewrite has to move, route or delete. A field keeps its
# place and size under another name: the layout and every sizeof stay as
# they were, so the only errors are touches. This build never links.
# Tiers: A the biped section (the bipeds' alone), B the unit section's
# motion, posing and control fields (shared with vehicles), C the object
# section's root, link and pose fields (shared with every object type).
TICK2 = os.environ.get("PSP_TICK2", "") == "1"
# slice 1's parts on by default under PSP_TICK2=biped (the lead 2026-11-24: the sweep reuse's reach guard, srreach1,
# 13:2x), each still off with its switch at 0 (PSP_SWEEPREUSE=0 ...) or its keep word at run time (sweepreuseoff);
# outside a biped build each stays opt-in at 1. The motion pass left these defaults 2026-11-25 (TICK2_MOTIONPASS)
def slice1_default(name):
    value = os.environ.get(name, "")
    return value == "1" or (value == "" and os.environ.get("PSP_TICK2", "") == "biped")
TICK2_PREFIX = "tick2_owned_"
TICK2_FIELDS = {
    "source/units/bipeds.h": ("_biped_datum", [  # tier A, whole
        "flags", "landing_recovery_counter", "landing_recovery_time", "state", "elevator_ticks",
        "elevator_object_index", "support_surface_index", "pathfinding_surface_index", "pathfinding_point",
        "last_pathfinding_attempt_time", "last_pathfinding_surface_index", "impact_target_object_index",
        "last_falling_communication_time", "bump_object_index", "bump_ticks", "airborne_ticks", "slipping_ticks",
        "stop_ticks", "jump_recovery_timer", "player_melee_ticks", "player_melee_attack_tick", "landing",
        "crouch", "bank", "ground_plane", "limp_body_current_relaxation_iterations",
        "limp_body_max_relaxation_iterations"]),
    "source/units/units.h": ("_unit_datum", [
        # tier B1: motion's own
        "aiming_vector", "aiming_velocity", "looking_vector", "looking_velocity", "animation", "mouth_aperture",
        "seat_last_position", "seat_last_velocity", "seat_acceleration", "seat_desired_acceleration",
        # tier B2: the controller's hand-over
        "control_flags", "desired_facing_vector", "desired_aiming_vector", "desired_looking_vector", "throttle",
        "aiming_speed", "primary_trigger", "current_zoom_level"]),
    "source/objects/objects.h": ("_object_datum", [  # tier C
        "position", "translational_velocity", "forward", "up", "angular_velocity", "location",
        "bounding_sphere_center", "bounding_sphere_radius", "animation", "original_node_orientations",
        "node_orientations", "node_matrices"]),
}
def tick2_poison(tree):
    if not TICK2:
        return 0
    import re
    done = 0
    for rel, (struct, fields) in TICK2_FIELDS.items():
        path = os.path.join(tree, rel)
        text = open(path, errors="surrogateescape").read()
        m = re.search(r"\nstruct %s\n\{\n(.*?)\n\};" % struct, text, re.S)
        if not m:
            check_fail("psp_fixups: TICK2: struct %s not found in %s" % (struct, rel))
            continue
        body = m.group(1)
        for field in fields:
            # the member's declaration: its name, then an array bound or the semicolon
            body, n = re.subn(r"(?m)^(\t[^\n;]*?[ \*])%s((?:\[[^\]\n]*\])*;)" % field,
                              lambda d: d.group(1) + TICK2_PREFIX + field + d.group(2), body)
            if n != 1:
                check_fail("psp_fixups: TICK2: %s.%s is declared %d times in %s, expected once" % (struct, field, n, rel))
            done += n
        if not CHECK_ONLY:
            open(path, "w", errors="surrogateescape").write(text[:m.start(1)] + body + text[m.end(1):])
    return done
print("psp_fixups: the tick rewrite's count: %d datum fields without their names (TICK2)" % tick2_poison(TREE))

# PSP_TICK2=root: the world store's ROOT section (the lab's
# tick_store_spec_v1.md, step 1b). The object datum's root fields are read and
# written in the store's record, reached through one pointer in the datum, and
# the datum shrinks by what left it: every type's datum size and the engine's
# offset checks on object-family datums move with it. The record array is game
# state out of the object pool's bytes (the game state is full), so the
# collector counts the store's spare records as free pool: it trips where it
# trips today (spec section 23). Runs after every FIXES group, on the text as
# they left it.
TICK2_ROOT = os.environ.get("PSP_TICK2", "") in ("root", "anim", "unit", "pose", "biped")
# PSP_TICK2=anim (step 1c-1): the ANIM section too, its records in a second array that shares
# ROOT's slot (spec section 30; the lead's design (b), 2026-11-23)
TICK2_ANIM = os.environ.get("PSP_TICK2", "") in ("anim", "unit", "pose", "biped")
# PSP_TICK2=unit (step 1c-2): unit.animation too, whole, in a unit section found by a 2-byte
# unit index in ROOT's record (spec section 32; the lead's ruling, 2026-11-23)
TICK2_UNIT = os.environ.get("PSP_TICK2", "") in ("unit", "pose", "biped")
# PSP_TICK2=pose (POSE's first step): the node blocks too, in the store's node arena (spec section 35)
TICK2_POSE = os.environ.get("PSP_TICK2", "") in ("pose", "biped")
# PSP_TICK2_PROOF=1 (with PSP_BIG_RAM=1; the lead, 2026-11-23 14:4x): the proof form. The store is outside
# the object pool and every datum keeps its old size, the moved bytes left in place as unnamed padding
# filled with a fixed pattern, so the pool holds blocks of the old build's sizes in its order and the
# collector's tests match the old build's by construction (the ship form's don't: they read a smaller
# pool). A reader that still lands on a moved field by a literal offset reads the pattern and parts at once.
TICK2_PROOF = os.environ.get("PSP_TICK2_PROOF", "") == "1"
TICK2_PROOF_BYTE = 0xA5
if TICK2_PROOF and os.environ.get("PSP_BIG_RAM", "") != "1":
    check_fail("psp_fixups: PSP_TICK2_PROOF=1 needs PSP_BIG_RAM=1 (the store's room outside the pool)")
# what leaves each datum: the record's 84 bytes less the pointer that stays (none in the proof form)
TICK2_ROOT_SHRINK = 0 if TICK2_PROOF else 0x50
# the store's capacity in records (spec section 23: the worst map's peak, 1,121 objects, and a margin)
# a map not in the table; and the free stack's room, past the table's largest count (c10's 1,440)
TICK2_STORE_SLOTS = int(os.environ.get("PSP_TICK2_SLOTS", "1280"))
TICK2_STORE_MOST = 1536
# the root run's place in object_datum (definition_index, then _object_datum's flags and magic number)
TICK2_ROOT_AT, TICK2_ROOT_END = 0x0C, 0x0C + 0x54
# the animation field's place in object_datum (struct object_animation_state, 12 bytes): all of it leaves
TICK2_ANIM_AT, TICK2_ANIM_END = 0x7C, 0x7C + 0x0C
# the three node block references at _object_datum's end (original_node_orientations, node_orientations,
# node_matrices, 4 bytes each): they leave with POSENEW's members cut (step 5, item 2's piece 3, docs/box_world_store.md
# section 17 'item 2, the members out'), as the switches that run that cut have it (TICK2_POSENEW, not STORECOUNT)
TICK2_POSE_MEMBERS = TICK2_POSE and os.environ.get("PSP_TICK2_POSENEW", "") == "1" and \
    os.environ.get("PSP_STORECOUNT", "") != "1"
TICK2_POSE_MEMBERS_AT, TICK2_POSE_MEMBERS_END = 0x198, 0x198 + 0x0C
# the runs that leave the datum, each with what it takes from the layout after it
TICK2_CUTS = [(TICK2_ROOT_AT, TICK2_ROOT_END, TICK2_ROOT_SHRINK)] + \
    ([(TICK2_ANIM_AT, TICK2_ANIM_END, 0 if TICK2_PROOF else TICK2_ANIM_END - TICK2_ANIM_AT)] if TICK2_ANIM else []) + \
    ([(TICK2_POSE_MEMBERS_AT, TICK2_POSE_MEMBERS_END, 0 if TICK2_PROOF else TICK2_POSE_MEMBERS_END - TICK2_POSE_MEMBERS_AT)]
     if TICK2_POSE_MEMBERS else [])
TICK2_SHRINK = sum(cut[2] for cut in TICK2_CUTS)
# the collector's line per map (its deletions, the pool's peak, peak live objects): on the
# root build, and on the old build with PSP_GCCOUNT=1 for the other side of the pair
# PSP_TICK2_REPORT=0 (the lead's heap menu (b1), 2026-11-23 21:2x): the store's reports, its census and the pass's
# posepassread reader stay out of the build (a ship build's ~7.5 KB); on by default, so the lab's runs keep them
TICK2_REPORT = os.environ.get("PSP_TICK2_REPORT", "1") != "0"
TICK2_GCCOUNT = (TICK2_ROOT and TICK2_REPORT) or os.environ.get("PSP_GCCOUNT", "") == "1"
# the collector's input (the lead, 2026-11-23 14:4x): the store is carved from the pool's tail, and its
# spare records and nodes are not tail a request can use, so by default the collector reads the pool as it
# is (it collects and compacts when the real tail runs short, where the old build might not: plays the same,
# not exact). PSP_TICK2_SPARE=1 keeps the earlier form, the pool's free plus the store's spare, which
# matches the old build's tests but can leave the tail short (tick2pose1's ARRAY FULL)
TICK2_SPARE_READ = os.environ.get("PSP_TICK2_SPARE", "") == "1"
TICK2_ROOT_FIELDS = ["position", "translational_velocity", "forward", "up", "angular_velocity", "location",
                     "bounding_sphere_center", "bounding_sphere_radius"]
TICK2_ROOT_DECL = """	real_point3d position;
	real_vector3d translational_velocity;
	real_vector3d forward;
	real_vector3d up;
	real_vector3d angular_velocity;
	struct location location;
	real_point3d bounding_sphere_center;
	real bounding_sphere_radius;
"""
# PSP_TICK2=anim: the ANIM section's array, and the one way from a record to its slot
TICK2_ANIM_DECL = r"""/* the ANIM section (TICK2 anim): an object's animation state, at its record's slot */
extern struct object_animation_state *tick2_anims;
/* one record in every section: a chunk holds its 64 ROOT records, then their 64 ANIM records */
#define TICK2_RECORD_BYTES ((long)(sizeof(struct tick2_root) + sizeof(struct object_animation_state)))
long tick2_overflow_slot(const struct tick2_root *record);
/* the store's key: a record's slot, the same index in every section (the map's records first,
then slots + 64 * chunk + place in the overflow chunks) */
static inline long tick2_slot_of(const struct tick2_root *record)
{
	unsigned long slot = (unsigned long)(record - tick2_roots);

	return slot < (unsigned long)tick2_store->slots ? (long)slot : tick2_overflow_slot(record);
}
static inline struct object_animation_state *tick2_anim_of(const struct tick2_root *record)
{
	long slot = tick2_slot_of(record);

	if (slot < tick2_store->slots)
		return &tick2_anims[slot];
	slot -= tick2_store->slots;
	return (struct object_animation_state *)(tick2_store->chunk[slot / TICK2_CHUNK] + TICK2_CHUNK) + slot % TICK2_CHUNK;
}
"""
TICK2_ANIM_FIELD = "\tstruct object_animation_state animation;\n"
TICK2_ANIM_CODE = r"""
/* an overflow record's slot (the inline tick2_slot_of's far side): slots + 64 * its chunk + its place */
long tick2_overflow_slot(const struct tick2_root *record)
{
	long c;
	static int told;

	for (c = 0; c < TICK2_CHUNKS; c++)
		if (tick2_store->chunk[c] && record >= tick2_store->chunk[c] && record < tick2_store->chunk[c] + TICK2_CHUNK)
			return tick2_store->slots + c * TICK2_CHUNK + (record - tick2_store->chunk[c]);
	if (!told++)
	{
		void platform_psp_log(const char *format, ...);

		platform_psp_log("tick2: a record %p in no section", (const void *)record);
	}
	return 0;
}

"""
TICK2_STORE_CODE = r"""
/* a record: this map's own, else a free one in an overflow chunk, else a new chunk from the pool */
static struct tick2_root *tick2_record_take(void)
{
	long c, k;

	if (tick2_free_count > 0)
	{
		struct tick2_root *record = &tick2_roots[tick2_free_records[--tick2_free_count]];

		if (tick2_free_count < tick2_free_low)
			tick2_free_low = tick2_free_count;
		return record;
	}
	for (c = 0; c < TICK2_CHUNKS; c++)
		if (tick2_store->chunk[c] && (tick2_store->chunk_free[c][0] | tick2_store->chunk_free[c][1]))
			break;
	if (c == TICK2_CHUNKS)
	{
		for (c = 0; c < TICK2_CHUNKS && tick2_store->chunk[c]; c++)
			;
		if (c == TICK2_CHUNKS || !memory_pool_block_allocate(object_memory_pool, (void **)&tick2_store->chunk[c],
			TICK2_CHUNK * TICK2_RECORD_BYTES))
			return NULL;
		tick2_store->chunk_was[c] = tick2_store->chunk[c];
		tick2_store->chunk_free[c][0] = tick2_store->chunk_free[c][1] = 0xFFFFFFFFUL;
	}
	for (k = 0; !(tick2_store->chunk_free[c][k >> 5] & (1UL << (k & 31))); k++)
		;
	tick2_store->chunk_free[c][k >> 5] &= ~(1UL << (k & 31));
	tick2_store->overflow_taken++;
	if (++tick2_store->overflow_live > tick2_store->overflow_peak)
		tick2_store->overflow_peak = tick2_store->overflow_live;
	return &tick2_store->chunk[c][k];
}

static void tick2_record_give(struct tick2_root *record)
{
	long c;

	if (record >= tick2_roots && record < tick2_roots + tick2_store->slots)
	{
		tick2_free_records[tick2_free_count++] = (short)(record - tick2_roots);
		return;
	}
	for (c = 0; c < TICK2_CHUNKS; c++)
		if (tick2_store->chunk[c] && record >= tick2_store->chunk[c] && record < tick2_store->chunk[c] + TICK2_CHUNK)
		{
			long k = record - tick2_store->chunk[c];

			tick2_store->chunk_free[c][k >> 5] |= 1UL << (k & 31);
			tick2_store->overflow_live--;
			if (tick2_store->chunk_free[c][0] == 0xFFFFFFFFUL && tick2_store->chunk_free[c][1] == 0xFFFFFFFFUL)
			{
				memory_pool_block_free(object_memory_pool, (void **)&tick2_store->chunk[c]);
				tick2_store->chunk[c] = tick2_store->chunk_was[c] = NULL;
			}
			return;
		}
}

static long tick2_chunk_free_records(void)
{
	long c, k, n = 0;

	for (c = 0; tick2_store && c < TICK2_CHUNKS; c++)
		if (tick2_store->chunk[c])
			for (k = 0; k < TICK2_CHUNK; k++)
				n += (tick2_store->chunk_free[c][k >> 5] >> (k & 31)) & 1;
	return n;
}

/* after the pool's compaction: the records in a chunk that moved are reached at its new place */
static void tick2_overflow_rebase(void)
{
	long c, i, moved = 0;

	for (c = 0; c < TICK2_CHUNKS; c++)
		moved |= tick2_store->chunk[c] != tick2_store->chunk_was[c];
	if (!moved)
		return;
	for (i = data_next_index(object_header_data, NONE); i != NONE; i = data_next_index(object_header_data, i))
	{
		struct object_header_datum *header = (struct object_header_datum *)datum_get(object_header_data, i);
		struct tick2_root **root;

		if (!header->datum)
			continue;
		root = &((struct object_datum *)header->datum)->object.root;
		for (c = 0; c < TICK2_CHUNKS; c++)
			if (tick2_store->chunk[c] != tick2_store->chunk_was[c] &&
				*root >= tick2_store->chunk_was[c] && *root < tick2_store->chunk_was[c] + TICK2_CHUNK)
			{
				*root = tick2_store->chunk[c] + (*root - tick2_store->chunk_was[c]);
				break;
			}
	}
	for (c = 0; c < TICK2_CHUNKS; c++)
		tick2_store->chunk_was[c] = tick2_store->chunk[c];
}
"""
def tick2_root_cut(tree):
    if not TICK2_ROOT:
        return 0
    import re
    def once(path, old, new):
        text = open(path, errors="surrogateescape").read()
        if text.count(old) != 1:
            check_fail("psp_fixups: TICK2 root: an anchor matches %d times in %s: %r" % (text.count(old), path, old[:60]))
            return
        if not CHECK_ONLY:
            open(path, "w", errors="surrogateescape").write(text.replace(old, new))
    # the record, and the union that keeps the datum's layout
    once(os.path.join(tree, "source/objects/objects.h"), "\nstruct _object_datum\n{\n",
         "\n/* the world store's ROOT record (TICK2 root) */\nstruct tick2_root\n{\n" + TICK2_ROOT_DECL +
         ("\tunsigned short unit_slot; /* TICK2 unit: the unit section's index, TICK2_UNIT_NONE if not a unit */\n#define TICK2_UNIT_NONE 0xFFFF\n" if TICK2_UNIT else "") +
         ("\tunsigned short pose_first; /* TICK2 pose: the object's first node in the arena (past its nodes, an overflow chunk's) */\n"
          "\tunsigned short pose_orient; /* its first node in the orientation run, TICK2_POSE_NONE if its type has none */\n"
          "\tunsigned char pose_count; /* its nodes, 0 for none */\n\tunsigned char pose_blocks; /* which of its three node blocks it has */\n" if TICK2_POSE else "") + (
         "};\nextern struct tick2_root *tick2_roots;\n"
         "/* the store's records for a map not in tick2_slots_for_map's table; each map takes its own count, never past\n"
         "TICK2_STORE_MOST, the free stack's room */\n"
         "#define TICK2_STORE_SLOTS %d\n"
         "#define TICK2_STORE_MOST %d\n"
         "/* past this map's records, overflow chunks of 64 as object pool blocks, given back when empty (spec section 27) */\n"
         "#define TICK2_CHUNK 64\n"
         "#define TICK2_CHUNKS (MAXIMUM_OBJECTS_PER_MAP / TICK2_CHUNK)\n"
         "struct tick2_store\n{\n\tlong slots, free_count, free_low, overflow_taken, overflow_live, overflow_peak;\n"
         "\tstruct tick2_root *chunk[TICK2_CHUNKS]; /* the pool's block references: compaction rewrites them */\n"
         "\tstruct tick2_root *chunk_was[TICK2_CHUNKS]; /* where each chunk was when its records were handed out */\n"
         "\tunsigned long chunk_free[TICK2_CHUNKS][TICK2_CHUNK / 32];\n"
         "\tshort free_records[TICK2_STORE_MOST];\n};\n"
         "extern struct tick2_store *tick2_store; /* game state, after the records */\n"
         "#define tick2_free_count (tick2_store->free_count)\n"
         "#define tick2_free_low (tick2_store->free_low)\n"
         "#define tick2_free_records (tick2_store->free_records)\n"
         % (TICK2_STORE_SLOTS, TICK2_STORE_MOST)) +
         (TICK2_ANIM_DECL if TICK2_ANIM else "#define TICK2_RECORD_BYTES ((long)sizeof(struct tick2_root))\n") +
         "\nstruct _object_datum\n{\n")
    path = os.path.join(tree, "source/objects/objects.h")
    text = open(path, errors="surrogateescape").read()
    m = re.search(r"\nstruct _object_datum\n\{\n(.*?)\n\};", text, re.S)
    if not m or m.group(1).count(TICK2_ROOT_DECL) != 1:
        check_fail("psp_fixups: TICK2 root: _object_datum's root fields aren't one run in objects.h")
    elif not CHECK_ONLY:
        body = m.group(1).replace(TICK2_ROOT_DECL,
            "\tstruct tick2_root *root; /* TICK2 root: the fields live in the store's record */\n" +
            ("\tunsigned char tick2_proof_root[0x50]; /* TICK2 proof: the old layout's bytes, a fixed pattern */\n" if TICK2_PROOF else ""))
        if TICK2_ANIM:
            if body.count(TICK2_ANIM_FIELD) != 1:
                check_fail("psp_fixups: TICK2 anim: _object_datum's animation field isn't one line in objects.h")
            body = body.replace(TICK2_ANIM_FIELD,
                "\tunsigned char tick2_proof_anim[sizeof(struct object_animation_state)] __attribute__((aligned(__alignof__(struct object_animation_state)))); /* TICK2 proof */\n"
                if TICK2_PROOF else "")
        open(path, "w", errors="surrogateescape").write(text[:m.start(1)] + body + text[m.end(1):])
    # every touch written x->object.<field> or x.object.<field>
    pattern = re.compile(r"((?:->|\.)\s*object\.)(%s)\b" % "|".join(TICK2_ROOT_FIELDS))
    # biped motion's window (BIPEDMOVE) held its own copy of these fields: the record is their one home now
    window = re.compile(r"PSP_BMSW?\((\w+), object\.(%s)((?:\.\w+)*)\)" % "|".join(TICK2_ROOT_FIELDS))
    anim = re.compile(r"\b(\w+->(?:object\.)?)object\.animation\b")
    anim_window = re.compile(r"PSP_BMSW?\((\w+), object\.animation((?:\.\w+)*)\)")
    touched = 0
    for root, dirs, files in os.walk(os.path.join(tree, "source")):
        for name in files:
            if not name.endswith((".c", ".h")):
                continue
            path = os.path.join(root, name)
            text = open(path, errors="surrogateescape").read()
            text, n = pattern.subn(r"\1root->\2", text)
            text, n2 = window.subn(r"\1->object.root->\2\3", text)
