# PSP_TICK2_POSEPASS=1 (with PSP_TICK2=pose; spec section 33, the lead 2026-11-23 16:4x and 18:4x): the posing pass.
# Both update paths (object_update and the port's lean path) end with the same tail after motion: the pose, the
# elevator's carry, function values and colours, lights, the children's updates, then postprocess. Phase 1 (the
# loop) runs each object's motion and its children's, skipping the tail's pose-dependent work, and lists each root
# it reaches; phase 2 (after every loop of objects_update) walks the list and runs each root's tail, children's
# tails inside it, so parents still come before children and IK still follows its pose. The pose's skip
# decisions and the elevator's pre-move sample are taken once in phase 1 and kept for phase 2. A collision
# instance that reaches an object not yet posed this tick poses it first (pose-on-touch, counted). Off, the two
# phases are one, as the old build.
TICK2_POSEPASS = os.environ.get("PSP_TICK2_POSEPASS", "") == "1"
TICK2_PP_CODE = r"""
/* TICK2 posing pass (spec section 33) */
int tick2_pp_phase; /* 0: one pass, as the old build; 1: motion; 2: the tails; 3: a tree's pose at a read (touchorder) */
#define TICK2_PP_MOST 1536
static unsigned short tick2_pp_roots[TICK2_PP_MOST]; /* the roots' absolute indices: the handle is rebuilt from the header in phase 2 (the lead's heap menu (a), 2026-11-23 21:2x) */
static long tick2_pp_count;
static unsigned char tick2_pp_skip[MAXIMUM_OBJECTS_PER_MAP / 8 + 1]; /* psp_pose_half_skips' answer, from phase 1, a bit an object */
static unsigned char tick2_pp_dead[MAXIMUM_OBJECTS_PER_MAP / 8 + 1]; /* deleted in phase 1: no tail, even if its slot is reused that tick */
static unsigned long tick2_pp_early; /* touchorder: roots whose tree was posed at a read (phase 3), ahead of phase 2 */
static unsigned long tick2_pp_presolve[2]; /* touchorder posing a staged biped after its intent, before its solve: [0] in the intents and gather, [1] in the solves */
int psp_bipedstage_unsolved(long object_index); /* objects.c (FIXES_BIPEDSTAGE), the motion pass's census */
static unsigned char tick2_pp_touched[MAXIMUM_OBJECTS_PER_MAP / 8 + 1]; /* posed on touch this tick */
static unsigned char tick2_pp_seen[MAXIMUM_OBJECTS_PER_MAP / 8 + 1]; /* listed this tick: the biped stage updates its bipeds in more than one pass */
static unsigned char tick2_pp_busy[MAXIMUM_OBJECTS_PER_MAP / 8 + 1]; /* a root's phase-1 update under way: its own and its children's reads of it come in here */
static unsigned char tick2_pp_done[MAXIMUM_OBJECTS_PER_MAP / 8 + 1]; /* a listed root's first phase-1 update has returned: old had it whole by now */
static unsigned char tick2_pp_posed[MAXIMUM_OBJECTS_PER_MAP / 8 + 1]; /* posed (and post-processed) in phase 3: phase 2 runs the rest of its tail */
/* the pose gate's test. Phase 3 poses the objects it reaches, except one still inside object_new (no node blocks
yet: object_new poses it there), and marks them; phase 2 then skips their pose and post-processing, which phase 3
made at the read, and runs the rest of their tails (function values, lights, the elevator's riders) at its own time */
static int tick2_pp_posed_early(long object_index)
{
	long k = object_index & 0xFFFF;
	struct object_datum *object;

	if (k >= MAXIMUM_OBJECTS_PER_MAP)
		return 0;
	if (tick2_pp_phase == 2)
		return (tick2_pp_posed[k >> 3] >> (k & 7)) & 1;
	if (tick2_pp_phase != 3)
		return 0;
	object = object_try_and_get(object_index);
	if (!object || !object->object.root || object->object.root->pose_first == TICK2_POSE_NONE || !object->object.root->pose_count)
		return 1;
	tick2_pp_posed[k >> 3] |= (unsigned char)(1 << (k & 7));
	return 0;
}
/* "parentfirst" (the lead 2026-11-24 01:0x, (b)): old poses a parent before its children update, so phase 1 poses a
parent's own nodes there; phase 2 then leaves that pose as made and runs the parent's post-processing (after its
children's, as old) on the half-skip or NMSKIP answer phase 1 kept */
static unsigned char tick2_pp_parent[MAXIMUM_OBJECTS_PER_MAP / 8 + 1]; /* posed in phase 1, before its children */
static unsigned char tick2_pp_parent_skip[MAXIMUM_OBJECTS_PER_MAP / 8 + 1]; /* that pose was skipped (half-skip or NMSKIP) */
static unsigned long tick2_pp_parents; /* parents posed before their children, for the report */
static void tick2_pp_parent_done(long object_index, int skipped)
{
	long k = object_index & 0xFFFF;
	unsigned char bit = (unsigned char)(1 << (k & 7));

	if (k >= MAXIMUM_OBJECTS_PER_MAP)
		return;
	tick2_pp_parent[k >> 3] |= bit;
	if (skipped)
		tick2_pp_parent_skip[k >> 3] |= bit;
	else
		tick2_pp_parent_skip[k >> 3] &= (unsigned char)~bit;
	tick2_pp_parents++;
}
/* the pose gate's second test: in a tail, a parent posed in phase 1 is posed already */
static int tick2_pp_parent_posed(long object_index)
{
	long k = object_index & 0xFFFF;

	return tick2_pp_phase >= 2 && k < MAXIMUM_OBJECTS_PER_MAP && ((tick2_pp_parent[k >> 3] >> (k & 7)) & 1);
}
/* the post-processing gate's skip: phase 1's answer for a parent it posed, else this call's */
static int tick2_pp_skip_of(long object_index, int skipped)
{
	long k = object_index & 0xFFFF;

	if (tick2_pp_phase >= 2 && k < MAXIMUM_OBJECTS_PER_MAP && ((tick2_pp_parent[k >> 3] >> (k & 7)) & 1))
		return (tick2_pp_parent_skip[k >> 3] >> (k & 7)) & 1;
	return skipped;
}
/* a root's later phase-1 pass moves it again: its tree's early pose no longer stands, so phase 2 poses it */
static void tick2_pp_unpose(long object_index)
{
	while (object_index != NONE)
	{
		long k = object_index & 0xFFFF;
		struct object_datum *object = object_try_and_get(object_index);

		if (!object || k >= MAXIMUM_OBJECTS_PER_MAP)
			return;
		tick2_pp_posed[k >> 3] &= (unsigned char)~(1 << (k & 7));
		tick2_pp_unpose(object->object.first_child_object_index);
		object_index = object->object.parent_object_index != NONE ? object->object.next_object_index : NONE;
	}
}
static boolean object_update(long object_index);
/* the old-order rule (spec section 33; the lead 2026-11-23 22:3x; "touchorder"): a phase-1 read of another object's
pose (a touch or a getter) gives old's answer by its loop order. If phase 1 has finished the object's root's update, old
had updated it whole by now, IK included, so its root's tree is posed now (phase 3: the pose and its post-processing
only; the rest of the tail waits for phase 2, because a whole tail run inside another object's read made and removed
lights under it: tick2pc4's crash); if not, old would read it at
last tick's pose, so it's left as it stands. "Finished", not "reached": a root's own motion and its children's updates
read the root while its update is under way, and old poses it only after them (tick2touch4 parted c20 at tick 38 on
"reached": the tail ran in the middle of its own root's motion) */
static void tick2_pp_old_order(long object_index)
{
	long root = object_index, at;
	struct object_datum *walk = object_try_and_get(root);

	while (walk && walk->object.parent_object_index != NONE)
	{
		root = walk->object.parent_object_index;
		walk = object_try_and_get(root);
	}
	at = root & 0xFFFF;
	if (!walk || at >= MAXIMUM_OBJECTS_PER_MAP || !((tick2_pp_done[at >> 3] >> (at & 7)) & 1) ||
		((tick2_pp_busy[at >> 3] >> (at & 7)) & 1) || ((tick2_pp_dead[at >> 3] >> (at & 7)) & 1))
		return;
	if ((tick2_pp_posed[at >> 3] >> (at & 7)) & 1)
		return;
	/* the motion pass's census (tick_store_biped_plan.md, "The motion pass"): under bipedstage3 a staged biped's
	first update returns at its intent, so "done" can come before its solve; counted, by stage phase */
	{
		int unsolved = psp_bipedstage_unsolved(root);

		if (unsolved)
			tick2_pp_presolve[unsolved == 4]++;
	}
	tick2_pp_phase = 3;
	object_update(root);
	tick2_pp_phase = 1;
	tick2_pp_early++;
}
#define TICK2_PP_ELEVATORS 64
static struct { long object_index; real_point3d sample; } tick2_pp_elev[TICK2_PP_ELEVATORS];
static long tick2_pp_elev_count;
static unsigned long tick2_pp_ticks, tick2_pp_listed, tick2_pp_inline, tick2_pp_elev_lost, tick2_pp_touches, tick2_pp_gone;

/* the pose's half-skip, decided once: phase 1 decides and keeps it, phase 2 reads it */
static int tick2_pp_half_skips(long object_index, struct object_datum *object)
{
	long k = object_index & 0xFFFF;
	int skipped;

	if (tick2_pp_phase >= 2 && k < MAXIMUM_OBJECTS_PER_MAP)
		return (tick2_pp_skip[k >> 3] >> (k & 7)) & 1;
	skipped = psp_pose_half_skips(object_index, object);
	if (tick2_pp_phase == 1 && k < MAXIMUM_OBJECTS_PER_MAP)
	{
		if (skipped)
			tick2_pp_skip[k >> 3] |= (unsigned char)(1 << (k & 7));
		else
			tick2_pp_skip[k >> 3] &= (unsigned char)~(1 << (k & 7));
	}
	return skipped;
}
/* the elevator's sample before it moves: taken in phase 1, read back for the carry in phase 2 */
static boolean tick2_pp_elevator(long object_index, boolean machine, real_point3d *sample)
{
	long k;

	if (!machine)
		return FALSE;
	if (tick2_pp_phase >= 2)
	{
		for (k = 0; k < tick2_pp_elev_count; k++)
			if (tick2_pp_elev[k].object_index == object_index)
			{
				*sample = tick2_pp_elev[k].sample;
				return TRUE;
			}
		return FALSE;
	}
	if (!machine_elevator_sample(object_index, sample))
		return FALSE;
	if (tick2_pp_phase == 1)
	{
		if (tick2_pp_elev_count < TICK2_PP_ELEVATORS)
		{
			tick2_pp_elev[tick2_pp_elev_count].object_index = object_index;
			tick2_pp_elev[tick2_pp_elev_count].sample = *sample;
			tick2_pp_elev_count++;
		}
		else
			tick2_pp_elev_lost++;
	}
	return TRUE;
}
/* a collision instance reaching an object's nodes in phase 1: posed first, once a tick (the lead 17:5x) */
void tick2_pp_touch(long object_index)
{
	long k = object_index & 0xFFFF;
	struct object_datum *object;

	if (tick2_pp_phase != 1 || object_index == NONE || k >= MAXIMUM_OBJECTS_PER_MAP ||
		((tick2_pp_touched[k >> 3] >> (k & 7)) & 1))
		return;
	/* the control (posepassinline): every root's tail runs in its own update, so nothing is stale and a pose here
	would undo a pose's IK already made (tick2pass3 parted a30 that way) */
	if (PSP_KEEP_ONCE("posepassinline"))
		return;
	/* "posetouchoff" (the lead 2026-11-23 21:5x: give the touch whichever form matches old's answer): no pose on touch,
	so the collision test reads the matrices as they stand, last tick's pose with its IK for an object not yet reached,
	as old's inline order leaves an object later in the loop */
	if (PSP_KEEP_ONCE("posetouchoff"))
		return;
	/* "touchorder": the old-order rule (spec section 33) */
	if (PSP_KEEP_ONCE("touchorder"))
	{
		tick2_pp_old_order(object_index);
		return;
	}
	/* only an object whose nodes are made: one still inside object_new is posed there (its own pose-now) */
	object = object_try_and_get(object_index);
	if (!object || !object->object.root || object->object.root->pose_first == TICK2_POSE_NONE || !object->object.root->pose_count)
		return;
	tick2_pp_touched[k >> 3] |= (unsigned char)(1 << (k & 7));
	object_compute_node_matrices(object_index);
	tick2_pp_touches++;
	{
		/* "touchlog" (the lead 2026-11-23 21:5x: name the object c20's collision test reads at its parting): each touch
		pose with its game time, the object's tag and type */
		static int touchlog = -1;
		void platform_psp_log(const char *format, ...);
		extern int psp_keep(const char *name);

		if (touchlog < 0)
			touchlog = psp_keep("touchlog") ? 1 : 0;
		if (touchlog)
			platform_psp_log("touch: tick %ld object %08lx %s type %d", (long)game_time_get(), (unsigned long)object_index,
				tag_get_name(object->definition_index), (int)object_header_get(object_index)->type);
	}
}
/* the experiment posepassread (the lead, 2026-11-23 20:3x): in phase 1 a getter read of an object not yet posed
this tick poses it first, its parent chain root down, so the read sees this tick's pose but for IK (a phase-1 pose
has none); counted by file and line, with how many of the objects posed were units (whose IK the read lacks) */
#define TICK2_PP_SITES 256
static struct { char const *file; int line; unsigned long reads, posed, posed_units; } tick2_pp_site[TICK2_PP_SITES];
static int tick2_pp_posing; /* inside a read's poses: their own reads don't pose again */
static unsigned long tick2_pp_sites_lost;
long tick2_pp_read(long object_index, char const *file, int line)
{
	long chain[16], count = 0, at, k = object_index & 0xFFFF;
	unsigned long h;
	int probes;

	if (tick2_pp_phase != 1 || tick2_pp_posing || object_index == NONE || k >= MAXIMUM_OBJECTS_PER_MAP)
		return object_index;
	if (PSP_KEEP_ONCE("touchorder")) /* the old-order rule, for a getter's read as for a touch */
	{
		tick2_pp_posing = 1; /* the tail's own reads take the rule no further */
		tick2_pp_old_order(object_index);
		tick2_pp_posing = 0;
		return object_index;
	}
	if (!PSP_KEEP_ONCE("posepassread"))
		return object_index;
	/* the chain up to the root, then posed root down: a child's pose reads its parent's */
	for (at = object_index; at != NONE && count < 16; )
	{
		struct object_datum *object = object_try_and_get(at);

		if (!object)
			break;
		chain[count++] = at;
		at = object->object.parent_object_index;
	}
	h = ((unsigned long)file * 31UL + (unsigned long)line) % TICK2_PP_SITES;
	for (probes = 0; probes < TICK2_PP_SITES; probes++, h = (h + 1) % TICK2_PP_SITES)
		if (!tick2_pp_site[h].file || (tick2_pp_site[h].file == file && tick2_pp_site[h].line == line))
			break;
	if (probes == TICK2_PP_SITES)
		tick2_pp_sites_lost++;
	else
	{
		tick2_pp_site[h].file = file;
		tick2_pp_site[h].line = line;
		tick2_pp_site[h].reads++;
	}
	tick2_pp_posing = 1;
	while (count > 0)
	{
		long index = chain[--count], j = index & 0xFFFF;
		struct object_datum *object = object_try_and_get(index);

		if (!object || j >= MAXIMUM_OBJECTS_PER_MAP || ((tick2_pp_touched[j >> 3] >> (j & 7)) & 1) ||
			!object->object.root || object->object.root->pose_first == TICK2_POSE_NONE || !object->object.root->pose_count)
			continue;
		tick2_pp_touched[j >> 3] |= (unsigned char)(1 << (j & 7));
		object_compute_node_matrices(index);
		if (probes < TICK2_PP_SITES)
		{
			tick2_pp_site[h].posed++;
			if (TEST_FLAG(_object_mask_unit, object->object.type))
				tick2_pp_site[h].posed_units++;
		}
	}
	tick2_pp_posing = 0;
	return object_index;
}

static void tick2_pp_begin(void)
{
	tick2_pp_count = tick2_pp_elev_count = 0;
	memset(tick2_pp_touched, 0, sizeof(tick2_pp_touched));
	memset(tick2_pp_seen, 0, sizeof(tick2_pp_seen));
	memset(tick2_pp_busy, 0, sizeof(tick2_pp_busy));
	memset(tick2_pp_done, 0, sizeof(tick2_pp_done));
	memset(tick2_pp_posed, 0, sizeof(tick2_pp_posed));
	memset(tick2_pp_parent, 0, sizeof(tick2_pp_parent));
	memset(tick2_pp_dead, 0, sizeof(tick2_pp_dead));
	tick2_pp_phase = 1;
	tick2_pp_ticks++;
}
static boolean object_update(long object_index);
static void tick2_pp_run(void)
{
	long k;

	tick2_pp_phase = 2;
	for (k = 0; k < tick2_pp_count; k++)
	{
		long index = tick2_pp_roots[k];
		struct datum_header *header = (struct datum_header *)((byte *)object_header_data->data + object_header_data->size * index);

		/* a root deleted in phase 1 (a projectile that detonated) has no tail, nor has an object that took its slot */
		if (((tick2_pp_dead[index >> 3] >> (index & 7)) & 1) || !header->identifier)
			tick2_pp_gone++;
		else
			object_update(((long)(unsigned short)header->identifier << 16) | index);
	}
	tick2_pp_phase = 0;
}
void tick2_pp_deleted(long object_index)
{
	long k = object_index & 0xFFFF;

	if (tick2_pp_phase == 1 && k < MAXIMUM_OBJECTS_PER_MAP)
		tick2_pp_dead[k >> 3] |= (unsigned char)(1 << (k & 7));
}
void platform_psp_log(const char *format, ...);
void tick2_pp_report(const char *label, int level_end)
{
	platform_psp_log("posepass (%s): %lu ticks; roots listed %lu (%lu a tick), run inline past the list %lu, gone by phase 2 %lu; elevators past the table %lu; posed on touch %lu (%lu a hundred ticks); trees posed at a read (touchorder) %lu, of them staged bipeds between intent and solve %lu in the intents, %lu in the solves (the motion census); parents posed before their children (parentfirst) %lu",
		label, tick2_pp_ticks, tick2_pp_listed, tick2_pp_ticks ? tick2_pp_listed / tick2_pp_ticks : 0,
		tick2_pp_inline, tick2_pp_gone, tick2_pp_elev_lost, tick2_pp_touches, tick2_pp_ticks ? tick2_pp_touches * 100 / tick2_pp_ticks : 0,
		tick2_pp_early, tick2_pp_presolve[0], tick2_pp_presolve[1], tick2_pp_parents);
	{
		int k, pass;

		/* the reads posepassread posed for, by site; projectiles.c's first (the lead's suspect), then the rest */
		for (pass = 0; pass < 2; pass++)
			for (k = 0; k < TICK2_PP_SITES; k++)
				if (tick2_pp_site[k].file && tick2_pp_site[k].posed)
				{
					char const *name = tick2_pp_site[k].file, *c;
					int projectile;

					for (c = name; *c; c++)
						if (*c == '/' || *c == '\\')
							name = c + 1;
					projectile = !strncmp(name, "projectile", 10);
					if (projectile != !pass)
						continue;
					platform_psp_log("posepassread (%s): %s:%d reads %lu, objects posed %lu, of them units without their IK %lu",
						label, name, tick2_pp_site[k].line, tick2_pp_site[k].reads, tick2_pp_site[k].posed, tick2_pp_site[k].posed_units);
				}
		if (tick2_pp_sites_lost)
			platform_psp_log("posepassread (%s): %lu reads past the site table", label, tick2_pp_sites_lost);
	}
	if (level_end)
	{
		tick2_pp_ticks = tick2_pp_listed = tick2_pp_inline = tick2_pp_elev_lost = tick2_pp_touches = tick2_pp_gone = tick2_pp_early = tick2_pp_parents = 0;
		tick2_pp_presolve[0] = tick2_pp_presolve[1] = 0;
		memset(tick2_pp_site, 0, sizeof(tick2_pp_site));
		tick2_pp_sites_lost = 0;
	}
}
"""
def tick2_posepass_cut(tree):
    if not TICK2_POSEPASS:
        return 0
    if not TICK2_POSE:
        check_fail("psp_fixups: PSP_TICK2_POSEPASS=1 needs PSP_TICK2=pose")
        return 0
    if TICK2_STALECENSUS:
        check_fail("psp_fixups: PSP_TICK2_POSEPASS=1 and PSP_TICK2_STALECENSUS=1 both wrap object_update; one at a time")
        return 0
    objects_c = os.path.join(tree, "source/objects/objects.c")
    objects_h = os.path.join(tree, "source/objects/objects.h")
    collision_c = os.path.join(tree, "source/physics/collision_models.c")
    c = open(objects_c, errors="surrogateescape").read()
    def body_of(text, head):
        if text.count(head) != 1:
            check_fail("psp_fixups: TICK2 posepass: %r matches %d times" % (head[:50], text.count(head)))
            return None
        at = text.index(head)
        return at, text.index("\n}\n", at) + 3
    def gate(body, pairs, name):
        for old, new in pairs:
            if body.count(old) != 1:
                check_fail("psp_fixups: TICK2 posepass: in %s, %r matches %d times" % (name, old[:60], body.count(old)))
                return None
            body = body.replace(old, new)
        return body
    def wrap(body, start, end, name):
        if body.count(start) != 1 or body.count(end) != 1:
            check_fail("psp_fixups: TICK2 posepass: in %s, the motion's ends match %d/%d" % (name, body.count(start), body.count(end)))
            return None
        a = body.index(start)
        b = body.index(end, a) + len(end)
        return body[:a] + "\t\tif (tick2_pp_phase < 2) /* TICK2 posepass: motion is phase 1's */\n\t\t{\n" + body[a:b] + "\t\t}\n" + body[b:]
    TICK2_PP_PARENT_FIRST = (
        "\t\t/* TICK2 posepass, \"parentfirst\": old poses a parent before its children update, so phase 1 poses its\n"
        "\t\town nodes here; its post-processing, after its children's, stays in phase 2's tail */\n"
        "\t\tif (tick2_pp_phase == 1 && object->object.first_child_object_index != NONE && PSP_KEEP_ONCE(\"parentfirst\"))\n"
        "\t\t{\n"
        "\t\t\tif (!TEST_FLAG(object->object.flags, _object_do_not_recompute_node_matrices_bit) && !psp_pose_skipped &&\n"
        "\t\t\t\t!(psp_nms_open && TEST_FLAG(PSP_NMS_TYPES, object->object.type) && psp_nms_may(object_index, object) &&\n"
        "\t\t\t\t\t(psp_pose_skipped = psp_nms_skip(object_index, object)) != 0))\n"
        "\t\t\t\t%s;\n"
        "\t\t\ttick2_pp_parent_done(object_index, psp_pose_skipped);\n"
        "\t\t}\n")
    common = [
        ("\t\tif (TEST_FLAG(object->object.flags, _object_garbage_bit))",
         "\t\tif (tick2_pp_phase < 2 && TEST_FLAG(object->object.flags, _object_garbage_bit)) /* TICK2 posepass */"),
        ("\t\tif ((*tick2_anim_of(object->object.root)).interpolation_frame_count)",
         "\t\tif (tick2_pp_phase < 2 && (*tick2_anim_of(object->object.root)).interpolation_frame_count) /* TICK2 posepass */"),
        ("elevator_sampled = object->object.type == _object_type_machine &&\n",
         "elevator_sampled = tick2_pp_elevator(object_index, object->object.type == _object_type_machine, &elevator_sample) /* TICK2 posepass */ &&\n"),
        ("if (!TEST_FLAG(object->object.flags, _object_do_not_recompute_node_matrices_bit) && !psp_pose_skipped &&",
         "if (tick2_pp_phase != 1 && !tick2_pp_posed_early(object_index) && !tick2_pp_parent_posed(object_index) && !TEST_FLAG(object->object.flags, _object_do_not_recompute_node_matrices_bit) && !psp_pose_skipped && /* TICK2 posepass */"),
        ("\t\tif (elevator_sampled)\n", "\t\tif ((tick2_pp_phase == 0 || tick2_pp_phase == 2) && elevator_sampled) /* TICK2 posepass */\n"),
    ]
    # the lean path
    lean = body_of(c, "static boolean psp_object_update_lean(\n\tlong object_index)\n{")
    if lean is None: return 0
    body = c[lean[0]:lean[1]]
    body = gate(body, common + [
        ("\t\t\tmachine_elevator_sample(object_index, &elevator_sample);\n", "\t\t\tTRUE;\n"),
        ("\t\tpsp_pose_skipped = psp_pose_half_skips(object_index, object);\n", "\t\tpsp_pose_skipped = tick2_pp_half_skips(object_index, object); /* TICK2 posepass */\n"),
        ("\t\tif (!(psp_fvp_open && psp_fvp_put_off(object_index, object)))\n",
         "\t\tif ((tick2_pp_phase == 0 || tick2_pp_phase == 2) && !(psp_fvp_open && psp_fvp_put_off(object_index, object))) /* TICK2 posepass */\n"),
        ("\t\tif (TEST_FLAG(object->object.flags, _object_dynamic_lighting_recompute_bit) &&\n",
         "\t\tif ((tick2_pp_phase == 0 || tick2_pp_phase == 2) && TEST_FLAG(object->object.flags, _object_dynamic_lighting_recompute_bit) && /* TICK2 posepass */\n"),
        ("\t\tif (!psp_pose_skipped)\n\t\t{\n\t\t\tif (!TEST_FLAG(_object_mask_unit",
         "\t\tif (tick2_pp_phase != 1 && !tick2_pp_posed_early(object_index) && !tick2_pp_skip_of(object_index, psp_pose_skipped)) /* TICK2 posepass */\n\t\t{\n\t\t\tif (!TEST_FLAG(_object_mask_unit"),
        ("\t\tif (object->object.first_child_object_index!=NONE)\n\t\t{\n\t\t\tpsp_object_update_lean(object->object.first_child_object_index);",
         TICK2_PP_PARENT_FIRST % "object_compute_node_matrices_with(object_index, object, object_definition)" + "\t\tif (object->object.first_child_object_index!=NONE)\n\t\t{\n\t\t\tpsp_object_update_lean(object->object.first_child_object_index);"),
    ], "the lean path")
    if body is None: return 0
    body = wrap(body, "\t\tobject_type_update_for_type(object->object.type, object_index);\n",
                "\t\t\tobject_type_export_function_values_for_type(object->object.type, object_index);\n\t\t}\n", "the lean path")
    if body is None: return 0
    c = c[:lean[0]] + body + c[lean[1]:]
    # object_update
    head = "static boolean object_update(\n\tlong object_index)\n{"
    main = body_of(c, head)
    if main is None: return 0
    body = c[main[0]:main[1]]
    body = gate(body, common + [
        ("\t\t\tmachine_elevator_sample(object_index, &elevator_sample);\n", "\t\t\tTRUE;\n"),
        ("\t\tint psp_pose_skipped = psp_pose_half_skips(object_index, object);\n", "\t\tint psp_pose_skipped = tick2_pp_half_skips(object_index, object); /* TICK2 posepass */\n"),
        ("\t\tif (psp_fvp_open && psp_fvp_put_off(object_index, object)) /* psp_fixups.py (FIXES_FISSION) */\n",
         "\t\tif (tick2_pp_phase == 1 || tick2_pp_phase == 3 || (psp_fvp_open && psp_fvp_put_off(object_index, object))) /* psp_fixups.py (FIXES_FISSION); TICK2 posepass */\n"),
        ("\t\tif (\n\t\t\tTEST_FLAG(object->object.flags, _object_dynamic_lighting_recompute_bit) &&",
         "\t\tif ((tick2_pp_phase == 0 || tick2_pp_phase == 2) && /* TICK2 posepass */\n\t\t\tTEST_FLAG(object->object.flags, _object_dynamic_lighting_recompute_bit) &&"),
        ("\t\tif (!psp_pose_skipped)\n\t\t\tobject_postprocess_node_matrices(object_index);",
         "\t\tif (tick2_pp_phase != 1 && !tick2_pp_posed_early(object_index) && !tick2_pp_skip_of(object_index, psp_pose_skipped)) /* TICK2 posepass */\n\t\t\tobject_postprocess_node_matrices(object_index);"),
        ("\t\t// Update children (if we have any)\n",
         TICK2_PP_PARENT_FIRST % "psp_hoist ? object_compute_node_matrices_with(object_index, object, object_definition) : object_compute_node_matrices(object_index)" + "\t\t// Update children (if we have any)\n"),
        (head, head + r"""
	/* TICK2 posepass: phase 1 lists each root it reaches, for phase 2's tails; past the list, a root's subtree
	runs both phases at once, as the old build */
	if (tick2_pp_phase == 1 && object_get(object_index)->object.parent_object_index == NONE &&
		!((tick2_pp_busy[(object_index & 0xFFFF) >> 3] >> (object_index & 7)) & 1))
	{
		long k = object_index & 0xFFFF;
		unsigned char bit = (unsigned char)(1 << (k & 7));

		/* a root's later pass (the biped stage's second) is phase 1 again, but the old-order rule keys on the first */
		if ((tick2_pp_seen[k >> 3] & bit))
		{
			boolean result;

			if ((tick2_pp_posed[k >> 3] & bit))
				tick2_pp_unpose(object_index);
			tick2_pp_busy[k >> 3] |= bit;
			result = object_update(object_index);
			tick2_pp_busy[k >> 3] &= (unsigned char)~bit;
			return result;
		}
		tick2_pp_seen[k >> 3] |= bit;
		/* the keep word "posepassinline" (the lead's control, 2026-11-23 19:4x): every root takes the inline path, so
		both phases run back to back at the old moment through the new gates, and the build must be exact against old */
		if (tick2_pp_count < TICK2_PP_MOST && !PSP_KEEP_ONCE("posepassinline"))
		{
			boolean result;

			tick2_pp_roots[tick2_pp_count++] = (unsigned short)k;
			tick2_pp_listed++;
			/* its motion and its children's updates run under busy: the old-order rule leaves its pose alone until
			they return (old poses it only after them), then a read finds it done */
			tick2_pp_busy[k >> 3] |= bit;
			result = object_update(object_index);
			tick2_pp_busy[k >> 3] &= (unsigned char)~bit;
			tick2_pp_done[k >> 3] |= bit;
			return result;
		}
		else
		{
			boolean result;

			tick2_pp_inline++;
			tick2_pp_phase = 0;
			result = object_update(object_index);
			tick2_pp_phase = 1;
			return result;
		}
	}"""),
    ], "object_update")
    if body is None: return 0
    body = wrap(body, "\t\t\tif (psp_hoist)\n\t\t\t\tobject_type_update_for_type(object->object.type, object_index);\n",
                "\t\t\telse\n\t\t\t\tobject_type_export_function_values(object_index);\n", "object_update")
    if body is None: return 0
    c = c[:main[0]] + body + c[main[1]:]
    # the helpers before the lean path (machine_elevator_sample and psp_pose_half_skips are declared by then)
    lean_head = "static boolean psp_object_update_lean(\n\tlong object_index)\n{"
    c = c.replace(lean_head, TICK2_PP_CODE + "\n" + lean_head, 1)
    # the driver: phase 1 around every loop of objects_update, phase 2 before NMSKIP closes
    pairs = [("\tpsp_nms_open = psp_nms_begin(); /* psp_fixups.py (FIXES_NMSKIP) */\n",
              "\tpsp_nms_open = psp_nms_begin(); /* psp_fixups.py (FIXES_NMSKIP) */\n\ttick2_pp_begin(); /* TICK2 posepass: phase 1 */\n"),
             ("\tpsp_nmr_in_update = 0;\n", "\ttick2_pp_run(); /* TICK2 posepass: phase 2, the tails */\n\tpsp_nmr_in_update = 0;\n")]
    if TICK2_GCCOUNT: # the pass's report rides the collector's (none in a PSP_TICK2_REPORT=0 build)
        pairs.append(("\ttick2_sc_report(label, level_end); /* TICK2 stale census */\n" if TICK2_STALECENSUS else
                      "\tif (level_end)\n\t\tmemset(&tick2_gc, 0, sizeof(tick2_gc));\n",
                      "\ttick2_pp_report(label, level_end); /* TICK2 posepass */\n\tif (level_end)\n\t\tmemset(&tick2_gc, 0, sizeof(tick2_gc));\n"))
    for old, new in pairs:
        if c.count(old) != 1:
            check_fail("psp_fixups: TICK2 posepass: %r matches %d times" % (old[:50], c.count(old)))
            return 0
        c = c.replace(old, new)
    # the report needs its declaration before the collector's report, which sits earlier in the file
    first = "\nboolean debug_object_garbage_collection;\n"
    if c.count(first) != 1:
        check_fail("psp_fixups: TICK2 posepass: the collector's flag matches %d times" % c.count(first))
        return 0
    c = c.replace(first, "\nvoid tick2_pp_report(const char *label, int level_end); /* TICK2 posepass */" + first)
    # collision: pose-on-touch
    h = open(objects_h, errors="surrogateescape").read()
    hp = "real_matrix4x3 *object_get_node_matrices(long object_index);\n"
    k = open(collision_c, errors="surrogateescape").read()
    ks = "\t\tinstance->matrices = object_get_node_matrices(object_index);\n"
    if h.count(hp) != 1 or k.count(ks) != 1:
        check_fail("psp_fixups: TICK2 posepass: collision anchors %d/%d" % (h.count(hp), k.count(ks)))
        return 0
    h = h.replace(hp, hp + "void tick2_pp_touch(long object_index); /* TICK2 posepass: a stale object posed on touch */\n")
    proto = "short object_get_marker_by_name(long object_index, char const *name, struct object_marker *markers, short maximum_marker_count);\n"
    if h.count(proto) != 1:
        check_fail("psp_fixups: TICK2 posepass: the marker getter's prototype matches %d times" % h.count(proto))
        return 0
    if True:  # the wrappers carry the old-order rule (touchorder), so every pass build has them (2026-11-24)
      h = h.replace(proto, proto + r"""/* TICK2 posepass, the experiment posepassread: every getter read goes through tick2_pp_read by file and line */
long tick2_pp_read(long object_index, char const *file, int line);
#define object_get_node_matrices(o) ((object_get_node_matrices)(tick2_pp_read((o), __FILE__, __LINE__)))
#define object_get_node_matrix(o, n) ((object_get_node_matrix)(tick2_pp_read((o), __FILE__, __LINE__), (n)))
#define object_get_marker_by_name(o, a, b, k) ((object_get_marker_by_name)(tick2_pp_read((o), __FILE__, __LINE__), (a), (b), (k)))
""")
    for old, new in [("real_matrix4x3 *object_get_node_matrices(\n", "real_matrix4x3 *(object_get_node_matrices)(\n"),
                     ("real_matrix4x3 *object_get_node_matrix(\n", "real_matrix4x3 *(object_get_node_matrix)(\n"),
                     ("short object_get_marker_by_name(\n", "short (object_get_marker_by_name)(\n")]:
        if c.count(old) != 1:
            check_fail("psp_fixups: TICK2 posepass: %r matches %d times" % (old[:40], c.count(old)))
            return 0
        c = c.replace(old, new)
    k = k.replace(ks, "\t\ttick2_pp_touch(object_index); /* TICK2 posepass: posed first if it's stale (the lead 17:5x) */\n" + ks)
    dd = "\tdatum_delete(data, object_index);\n\tobject_header->datum = NULL;\n"
    if c.count(dd) != 1:
        check_fail("psp_fixups: TICK2 posepass: object_header_delete's anchor matches %d times" % c.count(dd))
        return 0
    c = c.replace(dd, "\t{ extern void tick2_pp_deleted(long object_index); tick2_pp_deleted(object_index); } /* TICK2 posepass: no tail for a root deleted in phase 1 */\n" + dd)
    # the motion pass's census: which staged bipeds haven't run their solve yet (tick_store_biped_plan.md)
    for old, new in [
        ("static short psp_bipedstage_absolute[PSP_BIPEDSTAGE_MAXIMUM];\n",
         "static short psp_bipedstage_absolute[PSP_BIPEDSTAGE_MAXIMUM];\n"
         "static long psp_bipedstage_k = -1; /* TICK2 posepass: the solve under way (the motion census) */\n"
         "/* 3 in the intents and gather for any staged root, 4 in the solves for one later in the list; else 0 */\n"
         "int psp_bipedstage_unsolved(long object_index)\n{\n\tint k;\n\n"
         "\tif (psp_bipedstage_phase != 3 && !(psp_bipedstage_phase == 4 && psp_bipedstage_k >= 0))\n\t\treturn 0;\n"
         "\tfor (k = psp_bipedstage_phase == 4 ? psp_bipedstage_k + 1 : 0; k < psp_bipedstage_count; k++)\n"
         "\t\tif (psp_bipedstage_index[k] == object_index)\n\t\t\treturn psp_bipedstage_phase;\n\treturn 0;\n}\n"),
        ("\t\t\tpsp_bipedstage_phase = psp_bs3_on ? 4 : ",
         "\t\t\tpsp_bipedstage_k = k; /* TICK2 posepass: the motion census */\n\t\t\tpsp_bipedstage_phase = psp_bs3_on ? 4 : "),
        ("\t/* BIPEDMOVE 1c: a kept record whose solve didn't resume it written back */\n",
         "\tpsp_bipedstage_k = -1; /* TICK2 posepass: the motion census */\n\t/* BIPEDMOVE 1c: a kept record whose solve didn't resume it written back */\n"),
    ]:
        if c.count(old) != 1:
            check_fail("psp_fixups: TICK2 posepass: the motion census's anchor %r matches %d times" % (old[:50], c.count(old)))
            return 0
        c = c.replace(old, new)
    if not CHECK_ONLY:
        open(objects_c, "w", errors="surrogateescape").write(c)
        open(objects_h, "w", errors="surrogateescape").write(h)
        open(collision_c, "w", errors="surrogateescape").write(k)
    print("psp_fixups: TICK2 posepass: the poses in a pass after objects_update's loops")
    return 1
tick2_posepass_cut(TREE)

# PSP_TICK2_POSENEW=1 (with PSP_TICK2=pose or biped; slice 1's task 3, docs/box_world_store.md section 17, ruled by the
# lead 2026-11-25 01:06): posing as the store's code, in the design's order. Step 1, here: the store's entry points.
# store_pose_settle makes the owed nodes a reader wants, store_node_matrices and store_node_matrix settle and answer,
# and the engine's two getters settle through store_pose_settle, so every read settles in one place. Exact by
# construction: the same two tests in the same order at each getter (the node getter's left-out compute is now made
# after its node index is checked, which reads only the block's size). Next steps: the walk's 19 sites to the store,
# the getters' ~33 callers to the accessors, then the engine's walk and demand code deleted with their poisons.
TICK2_POSENEW = os.environ.get("PSP_TICK2_POSENEW", "") == "1"
TICK2_POSENEW_CODE = r"""
/* TICK2 posenew (slice 1's task 3; docs/box_world_store.md section 17): the store's posing entry points.
A pose is owed two ways, each kept in a side table of the store's (not a word in every record: section 17's note):
- a compute FIXES_NMSKIP left out, with its inputs as the skip found them, so the make reads what the eager compute
  would have read even if they changed since;
- means B's nodes a living biped's pose didn't make, made from the orientations that pose was given.
store_pose_settle is the one place a read makes them. On the ME the copy taken at the last hand-over decides, and an
owed read hands the actor back to the main CPU (psp_nms_me, psp_boxb_me): the ME never poses */
static inline __attribute__((always_inline)) void store_pose_settle_in(long object_index, unsigned long long want)
{
	PSP_NMS_READ(object_index); /* FIXES_NMSKIP's owed compute, whole */
#ifdef PSP_BOX_POSING
	PSP_BOXB_READ(object_index, want); /* means B's owed nodes, those wanted and their parents */
#endif
}

void store_pose_settle(long object_index, unsigned long long want)
{
	store_pose_settle_in(object_index, want);
}
"""
TICK2_POSENEW_ACCESSORS = r"""
/* TICK2 posenew: the store's accessors, a pose settled for what's read. Until step 3 they answer through the engine's
getters, which settle by store_pose_settle_in. The getters' names are in parentheses so posepass's read wrappers (macros
in objects.h) don't run a second time for a call that came through an accessor */
real_matrix4x3 const *store_node_matrices(long object_index)
{
	return (object_get_node_matrices)(object_index);
}

real_matrix4x3 const *store_node_matrix(long object_index, short node_index)
{
	return (object_get_node_matrix)(object_index, node_index);
}
"""
def tick2_posenew_cut(tree):
    if not TICK2_POSENEW:
        return 0
    if not TICK2_POSE:
        check_fail("psp_fixups: PSP_TICK2_POSENEW=1 needs PSP_TICK2=pose or biped")
        return 0
    objects_c = os.path.join(tree, "source/objects/objects.c")
    objects_h = os.path.join(tree, "source/objects/objects.h")
    c = open(objects_c, errors="surrogateescape").read()
    h = open(objects_h, errors="surrogateescape").read()
    def swap(text, old, new, where):
        if text.count(old) != 1:
            check_fail("psp_fixups: TICK2 posenew: %s's anchor %r matches %d times" % (where, old[:60], text.count(old)))
            return None
        return text.replace(old, new)
    nms = "\tPSP_NMS_READ(object_index); /* psp_fixups.py (FIXES_NMSKIP) */\n"
    whole = ("real_matrix4x3 *%sobject_get_node_matrices%s(\n\tlong object_index)\n{\n"
             "\t/* psp_fixups.py (FIXES_134 #nmreaders) */\n\tif (psp_nmr_on > 0)\n"
             "\t\tpsp_nmr_read(object_index, __builtin_return_address(0));\n" + nms)
    whole = whole % (("(", ")") if TICK2_POSEPASS else ("", ""))
    one = whole.replace("object_get_node_matrices", "object_get_node_matrix").replace(
        "\tlong object_index)\n", "\tlong object_index,\n\tshort node_index)\n")
    # the entry points before the first getter, which follows the NMSKIP and B tables and their read tests
    c = swap(c, whole, TICK2_POSENEW_CODE + "\n" + whole[:-len(nms)], "the matrices getter")
    if c is None: return 0
    c = swap(c, "#ifdef PSP_BOX_POSING\n\tPSP_BOXB_READ(object_index, ~0ull); /* the whole block: every owed node */\n#endif\n",
             "\tstore_pose_settle_in(object_index, ~0ull); /* TICK2 posenew: every owed node */\n", "the matrices getter")
    if c is None: return 0
    c = swap(c, one, one[:-len(nms)], "the node getter")
    if c is None: return 0
    c = swap(c, "#ifdef PSP_BOX_POSING\n\tPSP_BOXB_READ(object_index, 1ull << node_index); /* the node and its parents */\n#endif\n",
             "\tstore_pose_settle_in(object_index, 1ull << node_index); /* TICK2 posenew: the node and its parents */\n", "the node getter")
    if c is None: return 0
    # the accessors after the node getter's body
    at = c.index(one[:-len(nms)])
    end = c.index("\n}\n", at) + 3
    c = c[:end] + TICK2_POSENEW_ACCESSORS + c[end:]
    h = swap(h, "real_matrix4x3 *object_get_node_matrices(long object_index);\n",
             "real_matrix4x3 *object_get_node_matrices(long object_index);\n"
             "/* TICK2 posenew: the store's posing entry points (docs/box_world_store.md section 17) */\n"
             "void store_pose_settle(long object_index, unsigned long long want);\n"
             "real_matrix4x3 const *store_node_matrices(long object_index);\n"
             "real_matrix4x3 const *store_node_matrix(long object_index, short node_index);\n", "objects.h")
    if h is None: return 0
    if not CHECK_ONLY:
        open(objects_c, "w", errors="surrogateescape").write(c)
        open(objects_h, "w", errors="surrogateescape").write(h)
    print("psp_fixups: TICK2 posenew: the store's posing entry points; the engine's two getters settle through them")
    return 1
tick2_posenew_cut(TREE)

# PSP_TICK2_HOIST=1 (the lead 2026-11-23 22:5x, spec section 16's hoist rule): a section's record is reached once per
# object per function, its pointer held in a local, not once per field. posepair2a's PC samples (sierra-hw 45323181775)
# put the store's cost in its callers, where an accessor is inlined at every field. The local starts empty and is
# filled at the first use, so it's worked out exactly where the old text first worked it out, and never earlier (a
# record a function checks before it reads stays unread); the base variable must not be reassigned in the function
TICK2_HOIST = os.environ.get("PSP_TICK2_HOIST", "") == "1"
TICK2_HOIST_SITES = [
    ("source/units/units.c", "unit_preprocess_node_orientations", "unit"),
    ("source/units/units.c", "unit_update_animation", "unit"),
    ("source/objects/objects.c", "object_compute_node_matrices_with", "object"),
    ("source/objects/objects.c", "psp_nms_skip", "object"),
]
def tick2_hoist_cut(tree):
    if not TICK2_HOIST:
        return 0
    if not TICK2_ANIM:
        check_fail("psp_fixups: PSP_TICK2_HOIST=1 needs PSP_TICK2=anim or later")
        return 0
    total = 0
    for rel, name, base in TICK2_HOIST_SITES:
        path = os.path.join(tree, rel)
        text = open(path, errors="surrogateescape").read()
        m = re.search(r"\n[^\n#/*][^\n;]*\b%s\(\n?(?:[^;{]*?)\)\n\{\n" % re.escape(name), text)
        if not m:
            check_fail("psp_fixups: TICK2 hoist: %s's head isn't found in %s" % (name, rel))
            return 0
        start = m.end()
        end = text.find("\n}\n", start)
        body = text[start:end]
        if re.search(r"(?<![\w>.])%s\s*=[^=]" % base, body) and base == "object":
            check_fail("psp_fixups: TICK2 hoist: %s reassigns %s" % (name, base))
            return 0
        if base == "unit" and len(re.findall(r"(?<![\w>.])unit\s*=[^=]", body)) != 1:
            check_fail("psp_fixups: TICK2 hoist: %s assigns unit %d times, not once" % (name, len(re.findall(r"(?<![\w>.])unit\s*=[^=]", body))))
            return 0
        decls = ""
        for accessor, kind, local in (("tick2_unit_anim_of", "struct unit_animation", "tick2_h_unit"),
                                      ("tick2_anim_of", "struct object_animation_state", "tick2_h_anim")):
            use = "(*%s(%s->object.root))" % (accessor, base)
            n = body.count(use)
            if n < 2:
                continue
            body = body.replace(use, "(*(%s ? %s : (%s = %s(%s->object.root))))" % (local, local, local, accessor, base))
            decls += "\t%s *%s = NULL; /* TICK2 hoist: the section's record, worked out at its first use */\n" % (kind, local)
            total += n
        if decls:
            text = text[:start] + decls + body + text[end:]
            if not CHECK_ONLY:
                open(path, "w", errors="surrogateescape").write(text)
    print("psp_fixups: TICK2 hoist: %d section reads through a local, not the accessor each time" % total)
    return 1
tick2_hoist_cut(TREE)

# PSP_MOTIONCROSS=1 (a census build; lab tick_store_biped_plan.md, "The motion pass", M2): would the biped solve
# split at the move? Part 1 of a staged biped's solve runs from its resume at the move to biped_update_moving's
# return; part 2 is the rest (the landing and airborne states, melee, footsteps, discard, the animation tail, and
# object_update's own tail). Splitting runs every part 1 before every part 2, so a part 2 of biped j and a part 1
# of a later biped k swap order. The census marks every object a part touches through the object getters (and each
# biped's own datum by both its parts) and counts, per tick, the objects some j's part 2 and some later k's part 1
# both touched: a read or a write each, so 0 is safe and more is a list to refine. A line every 300 ticks.
MOTIONCROSS = os.environ.get("PSP_MOTIONCROSS", "") == "1"
MOTIONCROSS_CODE = r"""
/* PSP_MOTIONCROSS (tick_store_biped_plan.md, the motion pass): the solve's two parts' touches, per object a tick.
mcross2: a staged biped's own parts are kept apart from other bipeds' touches of it, and each part is checked for
whether it changed the biped's motion fields (the root's position to bounding sphere, the datum's flags and
damage flags), so a crossing reads as "real" only where the part on the far side changed what the other touched */
#define PSP_MC_OBJECTS 2048
#define PSP_MC_STAGE 256
#define PSP_MC_SITES 24
struct psp_mc_watch { unsigned char root[offsetof(struct tick2_root, unit_slot)]; unsigned long flags, damage_flags; };
static short psp_mc_k = -1, psp_mc_part = 0;
static long psp_mc_self = -1;
static short psp_mc_min2[PSP_MC_OBJECTS], psp_mc_max1[PSP_MC_OBJECTS], psp_mc_pos[PSP_MC_OBJECTS];
static unsigned short psp_mc_stamp[PSP_MC_OBJECTS], psp_mc_tick = 1;
static long psp_mc_list[PSP_MC_OBJECTS];
static short psp_mc_listed;
static unsigned char psp_mc_chg1[PSP_MC_STAGE], psp_mc_chg2[PSP_MC_STAGE];
static struct psp_mc_watch psp_mc_snap;
static unsigned long psp_mc_ticks, psp_mc_a, psp_mc_a_real, psp_mc_b, psp_mc_b_real, psp_mc_other, psp_mc_by_type[16];
static unsigned long psp_mc_moved1, psp_mc_moved2, psp_mc_parts;
static struct { void *site; unsigned long count; } psp_mc_sites[2][PSP_MC_SITES];
static void psp_mc_list_add(long object_index)
{
	long at = object_index & 0xFFFF;

	if (psp_mc_stamp[at] != psp_mc_tick)
	{
		psp_mc_stamp[at] = psp_mc_tick;
		psp_mc_min2[at] = 0x7FFF;
		psp_mc_max1[at] = -1;
		psp_mc_pos[at] = -1;
		if (psp_mc_listed < PSP_MC_OBJECTS)
			psp_mc_list[psp_mc_listed++] = object_index;
	}
}
static void psp_mc_site(int which, void *site)
{
	int n;

	for (n = 0; n < PSP_MC_SITES && psp_mc_sites[which][n].site && psp_mc_sites[which][n].site != site; n++);
	if (n < PSP_MC_SITES)
	{
		psp_mc_sites[which][n].site = site;
		psp_mc_sites[which][n].count++;
	}
}
long __attribute__((noinline)) psp_mc_touch(long object_index)
{
	if (psp_mc_k >= 0 && psp_bipedstage_phase == 4 && object_index != NONE && object_index != psp_mc_self &&
		(object_index & 0xFFFF) < PSP_MC_OBJECTS)
	{
		long at = object_index & 0xFFFF;

		psp_mc_list_add(object_index);
		if (psp_mc_part == 1 && psp_mc_k > psp_mc_max1[at])
			psp_mc_max1[at] = psp_mc_k;
		if (psp_mc_part == 2 && psp_mc_k < psp_mc_min2[at])
			psp_mc_min2[at] = psp_mc_k;
		/* the sites that make a crossing with a staged biped: a move touching one whose part 2 has run (A),
		a part 2 touching one whose move hasn't (B) */
		if (psp_mc_pos[at] >= 0 && psp_mc_part == 1 && psp_mc_pos[at] < psp_mc_k)
			psp_mc_site(0, __builtin_return_address(0));
		if (psp_mc_pos[at] >= 0 && psp_mc_part == 2 && psp_mc_pos[at] > psp_mc_k)
			psp_mc_site(1, __builtin_return_address(0));
	}
	return object_index;
}
static int psp_mc_take(long object_index, struct psp_mc_watch *watch)
{
	struct object_header_datum *header = (struct object_header_datum *)datum_try_and_get(object_header_data, object_index);

	if (!header || !header->datum || !header->datum->object.root)
		return 0;
	memcpy(watch->root, header->datum->object.root, sizeof(watch->root));
	watch->flags = header->datum->object.flags;
	watch->damage_flags = header->datum->object.damage_flags;
	return 1;
}
static int psp_mc_changed(long object_index, struct psp_mc_watch const *before)
{
	struct psp_mc_watch now;

	if (!psp_mc_take(object_index, &now))
		return 1; /* gone in its part: deleted is a change */
	return memcmp(&now, before, sizeof(now)) != 0;
}
static void psp_mc_close_part2(void)
{
	if (psp_mc_k >= 0 && psp_mc_part == 2 && psp_mc_k < PSP_MC_STAGE)
	{
		psp_mc_chg2[psp_mc_k] = (unsigned char)psp_mc_changed(psp_mc_self, &psp_mc_snap);
		psp_mc_moved2 += psp_mc_chg2[psp_mc_k];
	}
}
static void psp_mc_begin(short k, long biped_index)
{
	short n;

	psp_mc_close_part2();
	if (k == 0 || psp_mc_k < 0)
	{
		/* every staged biped's place in the list, known before any part runs */
		for (n = 0; n < psp_bipedstage_count && n < PSP_MC_STAGE; n++)
		{
			long at = psp_bipedstage_index[n] & 0xFFFF;

			if (at < PSP_MC_OBJECTS)
			{
				psp_mc_list_add(psp_bipedstage_index[n]);
				psp_mc_pos[at] = n;
			}
			psp_mc_chg1[n] = psp_mc_chg2[n] = 0;
		}
	}
	psp_mc_k = k;
	psp_mc_part = 1;
	psp_mc_self = biped_index;
	psp_mc_parts++;
	if (!psp_mc_take(biped_index, &psp_mc_snap))
		psp_mc_k = -1;
}
void psp_mc_part2(void)
{
	if (psp_mc_k >= 0 && psp_bipedstage_phase == 4 && psp_mc_part == 1)
	{
		if (psp_mc_k < PSP_MC_STAGE)
		{
			psp_mc_chg1[psp_mc_k] = (unsigned char)psp_mc_changed(psp_mc_self, &psp_mc_snap);
			psp_mc_moved1 += psp_mc_chg1[psp_mc_k];
		}
		psp_mc_part = 2;
		psp_mc_take(psp_mc_self, &psp_mc_snap);
	}
}
void platform_psp_log(const char *format, ...);
static void psp_mc_end(void)
{
	short n;

	psp_mc_close_part2();
	psp_mc_k = -1;
	psp_mc_part = 0;
	psp_mc_self = -1;
	for (n = 0; n < psp_mc_listed; n++)
	{
		long at = psp_mc_list[n] & 0xFFFF;
		short pos = psp_mc_pos[at];

		if (pos >= 0 && pos < PSP_MC_STAGE)
		{
			if (psp_mc_max1[at] > pos)
			{
				psp_mc_a++;
				psp_mc_a_real += psp_mc_chg2[pos];
			}
			if (psp_mc_min2[at] < pos)
			{
				psp_mc_b++;
				psp_mc_b_real += psp_mc_chg1[pos];
			}
		}
		else if (psp_mc_min2[at] < psp_mc_max1[at])
		{
			struct object_header_datum *header = (struct object_header_datum *)datum_try_and_get(object_header_data, psp_mc_list[n]);

			psp_mc_other++;
			psp_mc_by_type[header ? header->type & 15 : 15]++;
		}
	}
	psp_mc_listed = 0;
	if (++psp_mc_tick == 0)
		psp_mc_tick = 1;
	if (++psp_mc_ticks % 300 == 0)
	{
		int which, k;

		platform_psp_log("motioncross: %lu ticks, %lu solves (moves that changed the biped %lu, post-move parts that did %lu); "
			"A (a later move touched a biped whose post-move part ran) %lu, real %lu; B (a post-move part touched a biped not yet moved) %lu, real %lu; "
			"other objects crossing %lu (by type 0-11: %lu %lu %lu %lu %lu %lu %lu %lu %lu %lu %lu %lu)",
			psp_mc_ticks, psp_mc_parts, psp_mc_moved1, psp_mc_moved2, psp_mc_a, psp_mc_a_real, psp_mc_b, psp_mc_b_real, psp_mc_other,
			psp_mc_by_type[0], psp_mc_by_type[1], psp_mc_by_type[2], psp_mc_by_type[3], psp_mc_by_type[4], psp_mc_by_type[5],
			psp_mc_by_type[6], psp_mc_by_type[7], psp_mc_by_type[8], psp_mc_by_type[9], psp_mc_by_type[10], psp_mc_by_type[11]);
		for (which = 0; which < 2; which++)
			for (k = 0; k < PSP_MC_SITES && psp_mc_sites[which][k].site; k++)
				platform_psp_log("motioncross site %c: %p %lu", which ? 'B' : 'A', psp_mc_sites[which][k].site, psp_mc_sites[which][k].count);
	}
}
"""
def motioncross_cut(tree):
    if not MOTIONCROSS:
        return 0
    objects_c = os.path.join(tree, "source/objects/objects.c")
    objects_h = os.path.join(tree, "source/objects/objects.h")
    bipeds_c = os.path.join(tree, "source/units/bipeds.c")
    c = open(objects_c, errors="surrogateescape").read()
    h = open(objects_h, errors="surrogateescape").read()
    b = open(bipeds_c, errors="surrogateescape").read()
    names = ("object_get_and_verify_type", "object_try_and_get_and_verify_type", "psp_object_get_all")
    end = "\n#endif // __OBJECTS_H"
    if h.count(end) != 1:
        check_fail("psp_fixups: PSP_MOTIONCROSS: objects.h's end matches %d times" % h.count(end))
        return 0
    h = h.replace(end, "\n/* PSP_MOTIONCROSS: every getter's object counted by the motion census (objects.c) */\nlong psp_mc_touch(long object_index);\n" +
        "".join("#define %s(i, ...) %s(psp_mc_touch(i), ##__VA_ARGS__)\n" % (n, n) for n in names) + end)
    for n in names:
        # the definitions and the prototypes in objects.c, by the parenthesized name, so the macro leaves them alone
        hits = len(re.findall(r"(?m)^void \*%s\(" % n, c))
        if hits < 1:
            check_fail("psp_fixups: PSP_MOTIONCROSS: %s's definition not found" % n)
            return 0
        c = re.sub(r"(?m)^void \*%s\(" % n, "void *(%s)(" % n, c)
    for old, new in [
        ("static short psp_bipedstage_absolute[PSP_BIPEDSTAGE_MAXIMUM];\n",
         "static short psp_bipedstage_absolute[PSP_BIPEDSTAGE_MAXIMUM];\n" + MOTIONCROSS_CODE),
        ("\t\t\tpsp_bipedstage_phase = psp_bs3_on ? 4 : ",
         "\t\t\tif (psp_bs3_on)\n\t\t\t\tpsp_mc_begin(k, psp_bipedstage_index[k]); /* PSP_MOTIONCROSS */\n\t\t\tpsp_bipedstage_phase = psp_bs3_on ? 4 : "),
        ("\t/* BIPEDMOVE 1c: a kept record whose solve didn't resume it written back */\n",
         "\tpsp_mc_end(); /* PSP_MOTIONCROSS */\n\t/* BIPEDMOVE 1c: a kept record whose solve didn't resume it written back */\n"),
    ]:
        if c.count(old) != 1:
            check_fail("psp_fixups: PSP_MOTIONCROSS: %r matches %d times" % (old[:50], c.count(old)))
            return 0
        c = c.replace(old, new)
    old = "\t\tbiped_update_moving(biped_index, &animation, psp_held_biped, psp_held_definition);\n"
    if b.count(old) != 1:
        check_fail("psp_fixups: PSP_MOTIONCROSS: biped_update_moving's call matches %d times" % b.count(old))
        return 0
    b = b.replace(old, old + "\t\t{ extern void psp_mc_part2(void); psp_mc_part2(); } /* PSP_MOTIONCROSS: the solve's part 2 from here */\n")
    if not CHECK_ONLY:
        open(objects_c, "w", errors="surrogateescape").write(c)
        open(objects_h, "w", errors="surrogateescape").write(h)
        open(bipeds_c, "w", errors="surrogateescape").write(b)
    print("psp_fixups: PSP_MOTIONCROSS: the motion census (the solve's two parts' touches)")
    return 1
motioncross_cut(TREE)

# PSP_TICK2_MOTIONPASS=1 (lab tick_store_biped_plan.md, "The motion pass", M2; the lead 2026-11-24 13:4x: a
# plays-the-same change): the staged bipeds' solves split at the move. Every biped with a move runs it, in the
# stage's order (phase 4), then every biped runs the rest of its update and object_update's tail (phase 5), so
# each part's code runs back to back for all bipeds. Post-move reads of other bipeds (the held weapon's aim
# assist, the AI's helpers) then see every biped moved: at most one move's difference (tick2mcross2), the
# pre-approved class. The BIPEDMOVE record is written back at the move's end and not kept into phase 5.
# Keep word "motionpassoff": the build runs the stage as before (the exactness check).
# Off by default since 2026-11-25 (the lab's lead, 10:0x, on killread4's confirm): M2 reorders the bipeds' cluster
# relinks (every move before any rest), which parted c20_leg2 at tick 1260 (an infection form's pop met another
# first candidate), and relink order is order that shows in play. Opt-in at 1 in any build; motionpassoff still
# turns it off at run time in a build that has it.
TICK2_MOTIONPASS = os.environ.get("PSP_TICK2_MOTIONPASS", "") == "1"
def motionpass_cut(tree):
    if not TICK2_MOTIONPASS:
        return 0
    files = {k: os.path.join(tree, v) for k, v in (("objects", "source/objects/objects.c"),
        ("types", "source/objects/object_types.c"), ("bipeds", "source/units/bipeds.c"))}
    text = {k: open(v, errors="surrogateescape").read() for k, v in files.items()}
    pairs = [
        ("types", "(psp_bipedstage_phase == 2 || psp_bipedstage_phase == 4) && current_definition->datum_update == unit_update",
                  "(psp_bipedstage_phase == 2 || psp_bipedstage_phase == 4 || psp_bipedstage_phase == 5) && current_definition->datum_update == unit_update"),
        ("bipeds", "\tif (psp_bipedstage_phase == 4 && (psp_bs3_cur = psp_bs3_find(biped_index)) != NULL) /* (FIXES_BIPEDSTAGE) bipedstage3's solve */\n",
                   "\tif ((psp_bipedstage_phase == 4 || psp_bipedstage_phase == 5) && (psp_bs3_cur = psp_bs3_find(biped_index)) != NULL) /* (FIXES_BIPEDSTAGE) bipedstage3's solve; 5: the motion pass's rest */\n"),
        ("bipeds", "\t\tif (psp_bs3_resume == 1)\n\t\t\tgoto psp_bs3_resume_move;\n",
                   "\t\tif (psp_bs3_resume == 1)\n\t\t\tgoto psp_bs3_resume_move;\n\t\tif (psp_bs3_resume == 3) /* TICK2 motion pass: the rest after the move */\n\t\t\tgoto psp_bs3_resume_post;\n"),
        ("bipeds", "\t\tbiped_verify_object_vectors(biped_index, \"post-moving\");\n",
                   "\t\tif (psp_bipedstage_phase == 4 && psp_bs3_cur && psp_bs4_moving) /* TICK2 motion pass: stop after the move */\n"
                   "\t\t{\n\t\t\tpsp_bs3_cur->animation = animation;\n\t\t\tpsp_bs3_cur->stop = 3;\n\t\t\tgoto psp_bs3_out;\n\t\t}\n"
                   "psp_bs3_resume_post:\n\t\tpsp_bs3_resume = 0;\n"
                   "\t\tbiped_verify_object_vectors(biped_index, \"post-moving\");\n"),
        ("bipeds", "\tif (psp_bipedstage_phase == 4)\n\t{\n\t\tpsp_bms_stop();",
                   "\tif (psp_bipedstage_phase == 4 || psp_bipedstage_phase == 5)\n\t{\n\t\tpsp_bms_stop();"),
        ("bipeds", "static char psp_bs3_resume = 0;\n",
                   "static char psp_bs3_resume = 0;\n"
                   "static int psp_bs4_moving = 0; /* TICK2 motion pass: inside psp_bipedstage4_move */\n"),
        ("bipeds", "int psp_bipedstage3_kept(long biped_index)\n{\n\treturn psp_bs3_find(biped_index) != NULL;\n}\n",
                   "int psp_bipedstage3_kept(long biped_index)\n{\n\treturn psp_bs3_find(biped_index) != NULL;\n}\n"
                   "/* TICK2 motion pass: the move alone, stopped after it (psp_bs3_out writes the BIPEDMOVE record back) */\n"
                   "int psp_bipedstage4_move(long biped_index)\n{\n"
                   "\tstruct psp_bs3_record *record = psp_bs3_find(biped_index);\n\n"
                   "\tif (!record || record->stop != 1)\n\t\treturn 0;\n"
                   "\tpsp_bs4_moving = 1;\n\tbiped_update(biped_index);\n\tpsp_bs4_moving = 0;\n\treturn 1;\n}\n"),
        ("objects", "\t\t\tpsp_bipedstage_phase = psp_bs3_on ? 4 : ",
                    "\t\t\tpsp_bipedstage_phase = psp_bs3_on ? (psp_motion5 ? 5 : 4) : "),
        ("objects", "\t\t\tif (psp_bipedstage_phase == 4 && TEST_FLAG(header->datum->object.damage_flags, _object_dead_bit) &&",
                    "\t\t\tif ((psp_bipedstage_phase == 4 || psp_bipedstage_phase == 5) && TEST_FLAG(header->datum->object.damage_flags, _object_dead_bit) &&"),
        ("objects", "\tpsp_sweepme_end(); /* (FIXES_SWEEPME) */\n",
                    "\tpsp_sweepme_end(); /* (FIXES_SWEEPME) */\n"
                    "\t/* TICK2 motion pass (tick_store_biped_plan.md, M2): every move first, in the stage's order; then the\n"
                    "\tloop below runs each biped's rest as phase 5. \"motionpassoff\": as before */\n"
                    "\tif (psp_motionpass_on < 0)\n\t\tpsp_motionpass_on = !psp_keep(\"motionpassoff\");\n"
                    "\tpsp_motion5 = 0;\n"
                    "\tif (psp_bs3_on && psp_motionpass_on)\n\t{\n"
                    "\t\tfor (k = 0; k < psp_bipedstage_count; k++)\n\t\t{\n"
                    "\t\t\tif (psp_bipedstage_live(k, &header))\n\t\t\t{\n"
                    "\t\t\t\tpsp_bipedstage_phase = 4;\n"
                    "\t\t\t\tpsp_bipedstage4_move(psp_bipedstage_index[k]);\n\t\t\t}\n\t\t}\n"
                    "\t\tpsp_motion5 = 1;\n\t}\n"),
        ("objects", "\t/* BIPEDMOVE 1c: a kept record whose solve didn't resume it written back */\n",
                    "\tpsp_motion5 = 0; /* TICK2 motion pass */\n\t/* BIPEDMOVE 1c: a kept record whose solve didn't resume it written back */\n"),
        ("objects", "static short psp_bipedstage_absolute[PSP_BIPEDSTAGE_MAXIMUM];\n",
                    "static short psp_bipedstage_absolute[PSP_BIPEDSTAGE_MAXIMUM];\n"
                    "static int psp_motionpass_on = -1, psp_motion5 = 0; /* TICK2 motion pass */\n"
                    "int psp_bipedstage4_move(long biped_index); /* bipeds.c (TICK2 motion pass) */\n"),
    ]
    for key, old, new in pairs:
        if text[key].count(old) != 1:
            check_fail("psp_fixups: PSP_TICK2_MOTIONPASS: in %s, %r matches %d times" % (key, old[:60], text[key].count(old)))
            return 0
        text[key] = text[key].replace(old, new)
    if not CHECK_ONLY:
        for key, path in files.items():
            open(path, "w", errors="surrogateescape").write(text[key])
    print("psp_fixups: PSP_TICK2_MOTIONPASS: the biped solves split at the move (keep word motionpassoff)")
    return 1
motionpass_cut(TREE)


# PSP_POSECENSUS=1 (the lead 2026-11-23 21:2x: the parting census for c20's posing-pass shift): every node and marker
# getter read is hashed by its call site (file and line) into a per-tick sum, the object's datum index with what the
# getter answered; at each tick's end one line a site ("posecensus: T file:line reads hash"). Built into both sides of a
# comparison (the old build and the pass), so tools/posecensuscmp.py names the first tick each site's answers differ
# and statecmp the first field of play to part after it. With the pass it composes with posepassread's wrappers
# (the read is posed first, then hashed). An emulator instrument only: never in a PSP build.
POSECENSUS = os.environ.get("PSP_POSECENSUS", "") == "1"
def posecensus_cut(tree):
    if not POSECENSUS:
        return 0
    objects_c = os.path.join(tree, "source/objects/objects.c")
    objects_h = os.path.join(tree, "source/objects/objects.h")
    game_c = os.path.join(tree, "source/game/game.c")
    c = open(objects_c, errors="surrogateescape").read()
    h = open(objects_h, errors="surrogateescape").read()
    g = open(game_c, errors="surrogateescape").read()
    pp = "long tick2_pp_read(long object_index, char const *file, int line);\n"
    into = "tick2_pp_read((o), __FILE__, __LINE__)" if pp in h else "(o)"
    if pp in h:
        for line in ("#define object_get_node_matrices(o) ((object_get_node_matrices)(tick2_pp_read((o), __FILE__, __LINE__)))\n",
                     "#define object_get_node_matrix(o, n) ((object_get_node_matrix)(tick2_pp_read((o), __FILE__, __LINE__), (n)))\n",
                     "#define object_get_marker_by_name(o, a, b, k) ((object_get_marker_by_name)(tick2_pp_read((o), __FILE__, __LINE__), (a), (b), (k)))\n"):
            if h.count(line) != 1:
                check_fail("psp_fixups: POSECENSUS: posepass's wrapper %r matches %d times" % (line[:44], h.count(line)))
                return 0
            h = h.replace(line, "")
    else:
        for old, new in [("real_matrix4x3 *object_get_node_matrices(\n", "real_matrix4x3 *(object_get_node_matrices)(\n"),
                         ("real_matrix4x3 *object_get_node_matrix(\n", "real_matrix4x3 *(object_get_node_matrix)(\n"),
                         ("short object_get_marker_by_name(\n", "short (object_get_marker_by_name)(\n")]:
            if c.count(old) != 1:
                check_fail("psp_fixups: POSECENSUS: %r matches %d times" % (old[:40], c.count(old)))
                return 0
            c = c.replace(old, new)
    proto = "short object_get_marker_by_name(long object_index, char const *name, struct object_marker *markers, short maximum_marker_count);\n"
    if h.count(proto) != 1:
        check_fail("psp_fixups: POSECENSUS: the marker getter's prototype matches %d times" % h.count(proto))
        return 0
    h = h.replace(proto, proto + ("""/* POSECENSUS: every getter read hashed by its call site, per tick (psp_fixups.py) */
real_matrix4x3 *psp_pc_m(char const *file, int line, long object_index, real_matrix4x3 *answer);
short psp_pc_k(char const *file, int line, long object_index, struct object_marker *markers, short count);
#define object_get_node_matrices(o) (psp_pc_m(__FILE__, __LINE__, (o), (object_get_node_matrices)(INTO)))
#define object_get_node_matrix(o, n) (psp_pc_m(__FILE__, __LINE__, (o), (object_get_node_matrix)(INTO, (n))))
#define object_get_marker_by_name(o, a, b, k) (psp_pc_k(__FILE__, __LINE__, (o), (b), (object_get_marker_by_name)(INTO, (a), (b), (k))))
""").replace("INTO", into))
    c += r"""
/* POSECENSUS (psp_fixups.py): a per-tick sum of each call site's answers. A sum, so the order of reads within a tick
(which the pass changes) doesn't count, only what was read and what it answered */
#define PSP_PC_SITES 256
static struct { char const *file; int line; unsigned long reads, hash; } psp_pc_site[PSP_PC_SITES];
static int psp_pc_on = -1, psp_pc_stale_on = -1;
static unsigned long psp_pc_lost;
/* "stalereads" (the lead 2026-11-23 21:5x: does the posing pass leave scenery's matrices stale where they're read?):
the game time each object's matrices were last computed, and each node or marker read counted by where it's read
(collision, drawing, the rest) and the object's type, and how many of them found matrices not computed this tick */
long psp_pc_posed[2048];
/* "slice1census" (the lead 2026-11-23 23:2x, revision 2): (b) pose decodes that repeat a (model, animation, frame)
already decoded this tick or last; (c) poses no getter read before the object's next pose */
static int psp_s1_on = -1;
static unsigned char psp_s1_read[2048];
static unsigned long psp_s1_poses, psp_s1_unread, psp_s1_decodes, psp_s1_same_tick, psp_s1_last_tick;
static struct { const void *model, *animation; short frame; long tick; } psp_s1_seen[1024];
static int psp_s1_is_on(void)
{
	extern int psp_keep(const char *word);

	if (psp_s1_on < 0)
		psp_s1_on = psp_keep("slice1census") ? 1 : 0;
	return psp_s1_on;
}
void psp_s1_decode(const void *model, const void *animation, short frame)
{
	unsigned long h;
	long now;

	if (!psp_s1_is_on())
		return;
	now = game_time_get();
	h = ((unsigned long)(size_t)model * 31 + (unsigned long)(size_t)animation * 7 + (unsigned long)frame) % 1024;
	psp_s1_decodes++;
	if (psp_s1_seen[h].model == model && psp_s1_seen[h].animation == animation && psp_s1_seen[h].frame == frame)
	{
		if (psp_s1_seen[h].tick == now)
			psp_s1_same_tick++;
		else if (psp_s1_seen[h].tick == now - 1)
			psp_s1_last_tick++;
	}
	psp_s1_seen[h].model = model;
	psp_s1_seen[h].animation = animation;
	psp_s1_seen[h].frame = frame;
	psp_s1_seen[h].tick = now;
}
void psp_s1_posed(long object_index)
{
	long k = object_index & 2047;

	if (!psp_s1_is_on())
		return;
	psp_s1_poses++;
	if (psp_pc_posed[k] && !psp_s1_read[k])
		psp_s1_unread++;
	psp_s1_read[k] = 0;
}
static unsigned long psp_pc_stale_reads[3][NUMBER_OF_OBJECT_TYPES], psp_pc_stale_stale[3][NUMBER_OF_OBJECT_TYPES];
static unsigned long psp_pc_fnv(unsigned long h, void const *p, int n)
{
	unsigned char const *b = p;

	while (n--)
		h = (h ^ *b++) * 16777619UL;
	return h;
}
static void psp_pc_note(char const *file, int line, long object_index, void const *answer, int bytes)
{
	extern int psp_keep(const char *word);
	unsigned long k, h;

	if (psp_pc_on < 0)
		psp_pc_on = psp_keep("posecensus") ? 1 : 0;
	if (psp_pc_stale_on < 0)
		psp_pc_stale_on = psp_keep("stalereads") ? 1 : 0;
	if (psp_s1_on > 0 && object_index != NONE)
		psp_s1_read[object_index & 2047] = 1;
	if (psp_pc_stale_on && object_index != NONE)
	{
		struct object_header_datum *header = object_header_try_and_get(object_index);
		char const *base = strrchr(file, '/');
		int where;

		base = base ? base + 1 : file;
		where = !strncmp(base, "collision", 9) ? 0 : !strncmp(base, "render", 6) ? 1 : 2;
		if (header && header->type < NUMBER_OF_OBJECT_TYPES)
		{
			psp_pc_stale_reads[where][header->type]++;
			if (psp_pc_posed[object_index & 2047] != game_time_get())
				psp_pc_stale_stale[where][header->type]++;
		}
	}
	if (!psp_pc_on)
		return;
	k = ((unsigned long)(size_t)file * 31 + (unsigned long)line) % PSP_PC_SITES;
	while (psp_pc_site[k].file && (psp_pc_site[k].file != file || psp_pc_site[k].line != line))
		if (++k == PSP_PC_SITES)
			k = 0, psp_pc_lost++;
	if (psp_pc_lost > PSP_PC_SITES)
		return;
	psp_pc_site[k].file = file;
	psp_pc_site[k].line = line;
	h = psp_pc_fnv(2166136261UL, &object_index, sizeof object_index);
	if (answer)
		h = psp_pc_fnv(h, answer, bytes);
	psp_pc_site[k].reads++;
	psp_pc_site[k].hash += h;
}
real_matrix4x3 *psp_pc_m(char const *file, int line, long object_index, real_matrix4x3 *answer)
{
	psp_pc_note(file, line, object_index, answer, sizeof *answer);
	return answer;
}
short psp_pc_k(char const *file, int line, long object_index, struct object_marker *markers, short count)
{
	short i;

	if (count <= 0)
		psp_pc_note(file, line, object_index, NULL, 0);
	for (i = 0; i < count; i++)
		psp_pc_note(file, line, object_index, &markers[i].matrix, sizeof markers[i].matrix);
	return count;
}
void psp_pc_tick_end(long tick)
{
	void platform_psp_log(const char *format, ...);
	int k;

	if (psp_s1_on > 0 && tick % 900 == 0 && tick)
		platform_psp_log("slice1census: tick %ld: decodes %lu, repeating one made this tick %lu, last tick %lu; poses %lu, of them followed by another pose with no read between %lu",
			tick, psp_s1_decodes, psp_s1_same_tick, psp_s1_last_tick, psp_s1_poses, psp_s1_unread);
	if (psp_pc_stale_on > 0 && tick % 900 == 0 && tick)
	{
		static char const *const where_name[3] = { "collision", "drawing", "the rest" };
		int w, t;

		for (w = 0; w < 3; w++)
		{
			char line[512];
			int at = 0;

			for (t = 0; t < NUMBER_OF_OBJECT_TYPES; t++)
				if (psp_pc_stale_reads[w][t])
					at += snprintf(line + at, sizeof(line) - at, " type %d %lu/%lu", t, psp_pc_stale_stale[w][t], psp_pc_stale_reads[w][t]);
			platform_psp_log("stalereads: tick %ld, %s: stale/reads by object type (6 scenery, 7 machine, 8 control, 9 light fixture, 10 placeholder, 11 sound scenery):%s", tick, where_name[w], at ? line : " none");
		}
	}
	if (psp_pc_on <= 0)
		return;
	for (k = 0; k < PSP_PC_SITES; k++)
		if (psp_pc_site[k].reads)
		{
			char const *name = strrchr(psp_pc_site[k].file, '/');

			platform_psp_log("posecensus: %ld %s:%d %lu %08lx", tick, name ? name + 1 : psp_pc_site[k].file,
				psp_pc_site[k].line, psp_pc_site[k].reads, psp_pc_site[k].hash);
			psp_pc_site[k].reads = psp_pc_site[k].hash = 0;
		}
}
"""
    cw = "static void object_compute_node_matrices_with(\n\tlong object_index,\n\tstruct object_datum *object,\n\tstruct object_definition *object_definition)\n{\n"
    if c.count(cw) != 1:
        check_fail("psp_fixups: POSECENSUS: object_compute_node_matrices_with's head matches %d times" % c.count(cw))
        return 0
    c = c.replace(cw, cw + "\t{ extern void psp_s1_posed(long object_index); psp_s1_posed(object_index); } /* POSECENSUS slice1census */\n\t{ extern long psp_pc_posed[2048]; psp_pc_posed[object_index & 2047] = game_time_get(); } /* POSECENSUS stalereads */\n")
    tk = "\tunsigned long start, nested;\n\tboolean taken;\n\n\tif (psp_pose_time < 0 && psp_keep_loaded())"
    if c.count(tk) != 1:
        check_fail("psp_fixups: POSECENSUS: the pose take's head matches %d times" % c.count(tk))
        return 0
    c = c.replace(tk, "\tunsigned long start, nested;\n\tboolean taken;\n\n\t{ extern void psp_s1_decode(const void *model, const void *animation, short frame); psp_s1_decode(model, animation, frame); } /* POSECENSUS slice1census: every pose asked for */\n\tif (psp_pose_time < 0 && psp_keep_loaded())")
    gh = next((x for x in ("\t\t(PSP_STEP(\"psp_game_state_hash_tick\"), psp_game_state_hash_tick(game_time_get()));\n",
                           "\t\tpsp_game_state_hash_tick(game_time_get());\n") if g.count(x) == 1), "\t\tpsp_game_state_hash_tick(game_time_get());\n")
    if g.count(gh) != 1:
        check_fail("psp_fixups: POSECENSUS: game.c's tick-end hook matches %d times" % g.count(gh))
        return 0
    g = g.replace(gh, gh + "\t\t{ extern void psp_pc_tick_end(long tick); psp_pc_tick_end(game_time_get()); } /* POSECENSUS */\n")
    if not CHECK_ONLY:
        open(objects_c, "w", errors="surrogateescape").write(c)
        open(objects_h, "w", errors="surrogateescape").write(h)
        open(game_c, "w", errors="surrogateescape").write(g)
    print("psp_fixups: POSECENSUS: every node and marker read hashed by call site, per tick")
    return 1
posecensus_cut(TREE)

# PSP_PRODCOUNT=1 (the lead 2026-11-23 23:1x: the node-matrix product by unit, before 2a is built; emulator only):
# every matrix4x3_multiply counted by the unit that runs it (the main CPU's VFPU, its FPU, the ME's FPU), with a line
# each 300 ticks (a run cut at exitat60 ends before tick 1,800)
PRODCOUNT = os.environ.get("PSP_PRODCOUNT", "") == "1"
def prodcount_cut(tree):
    if not PRODCOUNT:
        return 0
    path = os.path.join(tree, "source/math/matrix_math.c")
    t = open(path, errors="surrogateescape").read()
    a = "\t{\n\t\tpsp_vfpu_matrix4x3_multiply(a, b, result);\n\t\treturn;\n\t}\n#endif\n\t{\n\treal const *a_elements = a->n[0];\n"
    if t.count(a) != 1:
        check_fail("psp_fixups: PRODCOUNT: matrix4x3_multiply's dispatch matches %d times" % t.count(a))
        return 0
    t = t.replace(a, """\t{
\t\tpsp_prod_count[0]++;
\t\tpsp_prod_report();
\t\tpsp_vfpu_matrix4x3_multiply(a, b, result);
\t\treturn;
\t}
\tpsp_prod_count[(psp_me_context || psp_cpu_is_me()) ? 2 : 1]++;
#endif
\t{
\treal const *a_elements = a->n[0];
""")
    head = "void matrix4x3_multiply(\n"
    if t.count(head) != 1:
        check_fail("psp_fixups: PRODCOUNT: matrix4x3_multiply's head matches %d times" % t.count(head))
        return 0
    t = t.replace(head, r"""/* PSP_PRODCOUNT (psp_fixups.py): node and other matrix products by the unit that ran them */
volatile unsigned long psp_prod_count[3]; /* the main CPU's VFPU, its FPU, the ME's FPU */
static void psp_prod_report(void)
{
	extern long game_time_get(void);
	void platform_psp_log(const char *format, ...);
	static long last = -1;
	long now = game_time_get();

	if (now > 0 && now % 300 == 0 && now != last)
	{
		last = now;
		platform_psp_log("prodcount: tick %ld, matrix products: the main CPU's VFPU %lu, its FPU %lu, the ME's FPU %lu",
			now, psp_prod_count[0], psp_prod_count[1], psp_prod_count[2]);
	}
}
""" + head)
    if not CHECK_ONLY:
        open(path, "w", errors="surrogateescape").write(t)
    print("psp_fixups: PRODCOUNT: matrix products counted by unit")
    return 1
