# PSP_COLLCENSUS=1, keep word "collcensus" (the lead 2026-11-23 23:4x, revision 2's next collection; emulator only):
# biped motion's pill sweep counted against last tick's (the same biped's inputs and answer), and its gather's object
# half (objects met in the clusters, past the broad phase, and of those the ones that give no features: what a tighter
# broad phase would skip), with a line each 300 ticks
COLLCENSUS = os.environ.get("PSP_COLLCENSUS", "") == "1"
def collcensus_cut(tree):
    if not COLLCENSUS:
        return 0
    bp = os.path.join(tree, "source/units/bipeds.c")
    cp = os.path.join(tree, "source/physics/collisions.c")
    b = open(bp, errors="surrogateescape").read()
    c = open(cp, errors="surrogateescape").read()
    call = "\t\tcollision_count = (psp_ask(1), collision_move_pill)(\n"
    if b.count(call) != 1:
        check_fail("psp_fixups: COLLCENSUS: the pill's call matches %d times" % b.count(call))
        return 0
    end = "\t\t\t16,\n\t\t\tcollisions);\n"
    at = b.index(call)
    if b.find(end, at) < 0:
        check_fail("psp_fixups: COLLCENSUS: the pill's call has no end")
        return 0
    e = b.index(end, at) + len(end)
    b = b[:at] + "\t\tpsp_cc_pill = 1; /* PSP_COLLCENSUS */\n" + b[at:e] + \
        "\t\tpsp_cc_pill = 0; /* PSP_COLLCENSUS */\n\t\tpsp_cc_sweep(physics->biped_index, collision_flags, &position, &velocity, physics->height, physics->width, collision_count, &clipped_position, &clipped_velocity, collisions);\n" + b[e:]
    decl = "\n/* PSP_COLLCENSUS (psp_fixups.py) */\nextern int psp_cc_pill;\nvoid psp_cc_sweep(long biped_index, unsigned long flags, real_point3d const *position, real_vector3d const *velocity, real height, real width, short count, real_point3d const *clipped_position, real_vector3d const *clipped_velocity, struct collision_plane const *collisions);\n"
    inc = b.index("\n", b.rindex("#include", 0, at)) + 1
    b = b[:inc] + decl + b[inc:]
    # the gather: objects met, past the broad phase, and with no features
    met = "#endif\n\t\t\t\t\t{\n\t\t\t\t\t\t/* port: (the far ones passed over on a packed copy\n"
    feat = "\t\t\t\t\t\t\tpsp_features_objects++;\n#endif\n\t\t\t\t\t\t\tobject_get_features_in_sphere(\n"
    fend = "\t\t\t\t\t\t\t\tignore_object_index,\n\t\t\t\t\t\t\t\tfeatures);\n\t\t\t\t\t\t}\n"
    if c.count(met) != 1 or c.count(feat) != 1:
        check_fail("psp_fixups: COLLCENSUS: the gather's anchors match %d/%d times" % (c.count(met), c.count(feat)))
        return 0
    c = c.replace(met, met[:-len("\t\t\t\t\t\t/* port: (the far ones passed over on a packed copy\n")] +
                  "\t\t\t\t\t\tif (psp_cc_pill) psp_cc[6]++; /* PSP_COLLCENSUS: an object met in the clusters */\n" +
                  "\t\t\t\t\t\t/* port: (the far ones passed over on a packed copy\n")
    fa = c.index(feat)
    if c.find(fend, fa) < 0:
        check_fail("psp_fixups: COLLCENSUS: the object features call has no end")
        return 0
    fe = c.index(fend, fa) + len(fend) - len("\t\t\t\t\t\t}\n")
    c = c[:fa] + "\t\t\t\t\t\t\tshort psp_cc_before = psp_cc_pill ? psp_cc_features(features) : 0; /* PSP_COLLCENSUS */\n" + c[fa:fe] + \
        "\t\t\t\t\t\t\tif (psp_cc_pill)\n\t\t\t\t\t\t\t{\n\t\t\t\t\t\t\t\tshort psp_cc_after = psp_cc_features(features);\n\n" \
        "\t\t\t\t\t\t\t\tpsp_cc[7]++;\n\t\t\t\t\t\t\t\tif (psp_cc_after == psp_cc_before)\n\t\t\t\t\t\t\t\t\tpsp_cc[8]++;\n" \
        "\t\t\t\t\t\t\t\tpsp_cc[10] += psp_cc_after - psp_cc_before;\n\t\t\t\t\t\t\t}\n" + c[fe:]
    head = "boolean collision_get_features_in_sphere(\n"
    if c.count(head) != 1:
        check_fail("psp_fixups: COLLCENSUS: collision_get_features_in_sphere matches %d times" % c.count(head))
        return 0
    c = c.replace(head, r"""/* PSP_COLLCENSUS (psp_fixups.py): the pill sweep against last tick's, and its gather's object half */
int psp_cc_pill; /* 1 while biped motion's pill sweep runs */
unsigned long psp_cc[12]; /* 0 sweeps, 1 same inputs as last tick, 2 of them the same answer, 3 the same answer from new inputs,
	6 objects met in the clusters, 7 past the broad phase, 8 of them with no features, 10 object features (4, 5, 9, 11 unused) */
static short psp_cc_features(struct collision_feature_list const *features)
{
	return features->count[_collision_feature_sphere] + features->count[_collision_feature_cylinder] + features->count[_collision_feature_prism];
}
static unsigned long psp_cc_hash(unsigned long h, void const *data, unsigned long size)
{
	unsigned char const *p = (unsigned char const *)data;

	while (size--)
		h = (h ^ *p++) * 16777619u;
	return h;
}
#define PSP_CC_SLOTS 2048
#define PSP_CC_TURNS 4 /* a biped's sweeps a tick, matched by their order */
static struct { long tick; unsigned char turns; unsigned long in[PSP_CC_TURNS], out[PSP_CC_TURNS]; } psp_cc_was[PSP_CC_SLOTS], psp_cc_now[PSP_CC_SLOTS];
void psp_cc_sweep(long biped_index, unsigned long flags, real_point3d const *position, real_vector3d const *velocity, real height, real width,
	short count, real_point3d const *clipped_position, real_vector3d const *clipped_velocity, struct collision_plane const *collisions)
{
	extern long game_time_get(void);
	void platform_psp_log(const char *format, ...);
	static long last_report = -1;
	long tick = game_time_get(), k = biped_index & (PSP_CC_SLOTS - 1);
	unsigned long in = 2166136261u, out = 2166136261u;
	int turn;

	if (!PSP_KEEP_ONCE("collcensus"))
		return;
	in = psp_cc_hash(in, &flags, sizeof(flags));
	in = psp_cc_hash(in, position, sizeof(*position));
	in = psp_cc_hash(in, velocity, sizeof(*velocity));
	in = psp_cc_hash(in, &height, sizeof(height));
	in = psp_cc_hash(in, &width, sizeof(width));
	out = psp_cc_hash(out, &count, sizeof(count));
	out = psp_cc_hash(out, clipped_position, sizeof(*clipped_position));
	out = psp_cc_hash(out, clipped_velocity, sizeof(*clipped_velocity));
	if (count > 0)
		out = psp_cc_hash(out, collisions, (unsigned long)(count < 16 ? count : 16) * sizeof(*collisions));
	if (psp_cc_now[k].tick != tick)
	{
		psp_cc_was[k] = psp_cc_now[k];
		psp_cc_now[k].tick = tick;
		psp_cc_now[k].turns = 0;
	}
	turn = psp_cc_now[k].turns;
	psp_cc[0]++;
	if (turn < PSP_CC_TURNS)
	{
		psp_cc_now[k].in[turn] = in;
		psp_cc_now[k].out[turn] = out;
		psp_cc_now[k].turns++;
		if (psp_cc_was[k].tick == tick - 1 && turn < psp_cc_was[k].turns)
		{
			if (psp_cc_was[k].in[turn] == in)
			{
				psp_cc[1]++;
				if (psp_cc_was[k].out[turn] == out)
					psp_cc[2]++;
			}
			else if (psp_cc_was[k].out[turn] == out)
				psp_cc[3]++;
		}
	}
	if (tick > 0 && tick % 300 == 0 && tick != last_report)
	{
		last_report = tick;
		platform_psp_log("collcensus: tick %ld: pill sweeps %lu, same inputs as the biped's last tick %lu, of them the same answer %lu; the same answer from new inputs %lu; the gather's objects met %lu, past the broad phase %lu, of them with no features %lu; object features %lu",
			tick, psp_cc[0], psp_cc[1], psp_cc[2], psp_cc[3], psp_cc[6], psp_cc[7], psp_cc[8], psp_cc[10]);
	}
}

""" + head, 1)
    if not CHECK_ONLY:
        open(bp, "w", errors="surrogateescape").write(b)
        open(cp, "w", errors="surrogateescape").write(c)
    print("psp_fixups: COLLCENSUS: the pill sweep and its gather counted")
    return 1
collcensus_cut(TREE)

# PSP_SWEEPREUSE=1 (slice 1's sweep reuse, the lead 2026-11-24 00:3x; tick2coll1: 35% of b30's pill sweeps repeat the
# same biped's last-tick inputs and every one got the same answer): biped motion's pill sweep takes last tick's answer
# when its inputs are byte-identical to that biped's sweep of the same order last tick and nothing its answer rests on
# can have changed: the same BSP, no breakable surface changed since, last tick's gather met no objects and the clusters
# it walked still hold none. On when built; keep word "sweepreuseoff" turns it off, "sweepreusecheck" sweeps anyway
# and counts any answer the reuse would have got wrong. A line each 300 ticks.
SWEEPREUSE = slice1_default("PSP_SWEEPREUSE")
def sweepreuse_cut(tree):
    if not SWEEPREUSE:
        return 0
    bp = os.path.join(tree, "source/units/bipeds.c")
    cp = os.path.join(tree, "source/physics/collisions.c")
    b = open(bp, errors="surrogateescape").read()
    c = open(cp, errors="surrogateescape").read()
    # the call as the pad path wraps it (PSP_PADPATH) or plain
    call = next((c for c in ("\t\tcollision_count = (psp_ask(1), collision_move_pill)(\n", "\t\tcollision_count = collision_move_pill(\n")
                 if b.count(c) == 1), "\t\tcollision_count = collision_move_pill(\n")
    end = "\t\t\t16,\n\t\t\tcollisions);\n"
    if b.count(call) != 1:
        check_fail("psp_fixups: SWEEPREUSE: the pill's call matches %d times" % b.count(call))
        return 0
    at = b.index(call)
    if b.find(end, at) < 0:
        check_fail("psp_fixups: SWEEPREUSE: the pill's call has no end")
        return 0
    e = b.index(end, at) + len(end)
    args = "physics->biped_index, collision_flags, &position, &velocity, physics->height, physics->width, &collision_count, &clipped_position, &clipped_velocity, collisions"
    b = b[:at] + ("\t\tif (!psp_sr_try(%s)) /* PSP_SWEEPREUSE */\n\t\t{\n\t\tpsp_sr_begin();\n" % args) + b[at:e] + \
        ("\t\tpsp_sr_store(%s);\n\t\t}\n" % args) + b[e:]
    inc = b.index("\n", b.rindex("#include", 0, at)) + 1
    b = b[:inc] + ("\n/* PSP_SWEEPREUSE (psp_fixups.py) */\n"
                   "boolean psp_sr_try(long biped_index, unsigned long flags, real_point3d const *position, real_vector3d const *velocity, real height, real width, short *count, real_point3d *clipped_position, real_vector3d *clipped_velocity, struct collision_plane *collisions);\n"
                   "void psp_sr_begin(void);\n"
                   "void psp_sr_store(long biped_index, unsigned long flags, real_point3d const *position, real_vector3d const *velocity, real height, real width, short *count, real_point3d *clipped_position, real_vector3d *clipped_velocity, struct collision_plane *collisions);\n") + b[inc:]
    cl = "\t\t\t\tif (structure_cluster_mark(cluster_index))\n\t\t\t\t{\n"
    met = "\t\t\t\t\t\t/* port: (the far ones passed over on a packed copy\n"
    head = "boolean collision_get_features_in_sphere(\n"
    for anchor_, name in ((met, "the object loop"), (head, "the gather's head")):
        if c.count(anchor_) != 1:
            check_fail("psp_fixups: SWEEPREUSE: %s matches %d times in collisions.c" % (name, c.count(anchor_)))
            return 0
    # the cluster mark inside the sphere gather (another gather in the file has the same lines)
    g0 = c.index(head)
    g1 = c.index("\n}\n", g0)
    if c.count(cl, g0, g1) != 1:
        check_fail("psp_fixups: SWEEPREUSE: the sphere gather's cluster mark matches %d times" % c.count(cl, g0, g1))
        return 0
    ci = c.index(cl, g0, g1) + len(cl)
    c = c[:ci] + "\t\t\t\t\tif (psp_sr_on_pill) psp_sr_cluster(cluster_index); /* PSP_SWEEPREUSE */\n" + c[ci:]
    c = c.replace(met, "\t\t\t\t\t\tif (psp_sr_on_pill) psp_sr_met++; /* PSP_SWEEPREUSE: an object in a walked cluster */\n" + met)
    c = c.replace(head, r"""/* PSP_SWEEPREUSE (psp_fixups.py): biped motion's pill sweep takes last tick's answer when nothing it rests on changed */
#define PSP_SR_SLOTS 64 /* bipeds, by their index's low bits (tagged: a clash only means no reuse) */
#define PSP_SR_TURNS 2 /* a biped's sweeps a tick, matched by their order */
#define PSP_SR_PLANES 2 /* answers with more planes aren't kept */
#define PSP_SR_CLUSTERS 8 /* gathers walking more clusters aren't kept */
struct psp_sr_record
{
	long biped_index, tick;
	unsigned long flags, breakable;
	real_point3d position, clipped_position;
	real_vector3d velocity, clipped_velocity;
	real height, width;
	short bsp, count, cluster_count;
	short clusters[PSP_SR_CLUSTERS];
	struct collision_plane planes[PSP_SR_PLANES];
};
static struct psp_sr_record psp_sr_records[PSP_SR_SLOTS][PSP_SR_TURNS];
static struct { long biped_index, tick; int turn; } psp_sr_turns[PSP_SR_SLOTS];
int psp_sr_on_pill; /* 1 while a kept sweep's gather runs */
int psp_sr_met;
static short psp_sr_cluster_list[PSP_SR_CLUSTERS], psp_sr_cluster_count; /* -1: too many */
static unsigned long psp_sr_counts[6]; /* sweeps, reused, inputs the same but refused, of them for objects, kept, wrong in the check */
static struct psp_sr_record *psp_sr_candidate; /* sweepreusecheck: the answer the reuse would have given */
static int psp_sr_turn_now;
static void psp_sr_cluster(short cluster_index)
{
	if (psp_sr_cluster_count >= 0 && psp_sr_cluster_count < PSP_SR_CLUSTERS)
		psp_sr_cluster_list[psp_sr_cluster_count++] = cluster_index;
	else
		psp_sr_cluster_count = -1;
}
static unsigned long psp_sr_breakable(long tick)
{
	static long hashed = -1;
	static unsigned long hash;

	if (tick != hashed)
	{
		byte const *bits = breakable_surface_flags_get();
		int k;

		hash = 2166136261u;
		for (k = 0; k < MAXIMUM_BREAKABLE_SURFACES_PER_MAP / 8; k++)
			hash = (hash ^ bits[k]) * 16777619u;
		hashed = tick;
	}
	return hash;
}
static int psp_sr_turn(long biped_index, long tick)
{
	long k = biped_index & (PSP_SR_SLOTS - 1);

	if (psp_sr_turns[k].biped_index != biped_index || psp_sr_turns[k].tick != tick)
	{
		psp_sr_turns[k].biped_index = biped_index;
		psp_sr_turns[k].tick = tick;
		psp_sr_turns[k].turn = 0;
	}
	return psp_sr_turns[k].turn++;
}
boolean psp_sr_try(long biped_index, unsigned long flags, real_point3d const *position, real_vector3d const *velocity, real height, real width,
	short *count, real_point3d *clipped_position, real_vector3d *clipped_velocity, struct collision_plane *collisions)
{
	extern long game_time_get(void);
	void platform_psp_log(const char *format, ...);
	static long last_report = -1;
	long tick = game_time_get();
	struct psp_sr_record *r;
	int k;

	psp_sr_candidate = NULL;
	psp_sr_turn_now = psp_sr_turn(biped_index, tick);
	if (tick > 0 && tick % 300 == 0 && tick != last_report)
	{
		last_report = tick;
		platform_psp_log("sweepreuse: tick %ld: pill sweeps %lu, reused %lu; the same inputs refused %lu (for objects %lu); kept %lu; wrong in the check %lu",
			tick, psp_sr_counts[0], psp_sr_counts[1], psp_sr_counts[2], psp_sr_counts[3], psp_sr_counts[4], psp_sr_counts[5]);
	}
	psp_sr_counts[0]++;
	if (PSP_KEEP_ONCE("sweepreuseoff") || psp_sr_turn_now >= PSP_SR_TURNS)
		return FALSE;
	r = &psp_sr_records[biped_index & (PSP_SR_SLOTS - 1)][psp_sr_turn_now];
	if (r->biped_index != biped_index || r->tick != tick - 1 || r->flags != flags || r->height != height || r->width != width ||
		memcmp(&r->position, position, sizeof(*position)) || memcmp(&r->velocity, velocity, sizeof(*velocity)))
		return FALSE;
	if (r->bsp != global_structure_bsp_index || r->breakable != psp_sr_breakable(tick) || r->cluster_count <= 0) /* none recorded: its objects unchecked (tick2sr1) */
	{
		psp_sr_counts[2]++;
		return FALSE;
	}
	for (k = 0; k < r->cluster_count; k++)
	{
		long reference_index;

		if (cluster_get_first_collideable_object(&reference_index, r->clusters[k]) != NONE)
		{
			psp_sr_counts[2]++;
			psp_sr_counts[3]++;
			return FALSE;
		}
	}
	if (PSP_KEEP_ONCE("sweepreusecheck"))
	{
		psp_sr_candidate = r;
		return FALSE;
	}
	*count = r->count;
	*clipped_position = r->clipped_position;
	*clipped_velocity = r->clipped_velocity;
	if (r->count > 0)
		memcpy(collisions, r->planes, r->count * sizeof(*collisions));
	r->tick = tick;
	psp_sr_counts[1]++;
	return TRUE;
}
void psp_sr_begin(void)
{
	psp_sr_on_pill = 1;
	psp_sr_met = 0;
	psp_sr_cluster_count = 0;
}
void psp_sr_store(long biped_index, unsigned long flags, real_point3d const *position, real_vector3d const *velocity, real height, real width,
	short *count, real_point3d *clipped_position, real_vector3d *clipped_velocity, struct collision_plane *collisions)
{
	extern long game_time_get(void);
	long tick = game_time_get();
	struct psp_sr_record *r;

	psp_sr_on_pill = 0;
	if (psp_sr_candidate)
	{
		struct psp_sr_record *was = psp_sr_candidate;

		if (was->count != *count || memcmp(&was->clipped_position, clipped_position, sizeof(*clipped_position)) ||
			memcmp(&was->clipped_velocity, clipped_velocity, sizeof(*clipped_velocity)) ||
			(*count > 0 && memcmp(was->planes, collisions, *count * sizeof(*collisions))))
		{
			void platform_psp_log(const char *format, ...);

			if (psp_sr_counts[5]++ < 8)
				platform_psp_log("sweepreuse: wrong at tick %ld, biped %lx: count %d against %d; position %s, velocity %s, planes %s; clusters %d",
					tick, (unsigned long)biped_index, (int)was->count, (int)*count,
					memcmp(&was->clipped_position, clipped_position, sizeof(*clipped_position)) ? "differs" : "same",
					memcmp(&was->clipped_velocity, clipped_velocity, sizeof(*clipped_velocity)) ? "differs" : "same",
					was->count != *count ? "-" : (*count > 0 && memcmp(was->planes, collisions, *count * sizeof(*collisions))) ? "differ" : "same",
					(int)was->cluster_count);
		}
	}
	if (psp_sr_turn_now >= PSP_SR_TURNS)
		return;
	r = &psp_sr_records[biped_index & (PSP_SR_SLOTS - 1)][psp_sr_turn_now];
	r->biped_index = NONE;
	if (psp_sr_met || psp_sr_cluster_count < 0 || *count > PSP_SR_PLANES)
		return;
	r->tick = tick;
	r->flags = flags;
	r->position = *position;
	r->velocity = *velocity;
	r->height = height;
	r->width = width;
	r->bsp = global_structure_bsp_index;
	r->breakable = psp_sr_breakable(tick);
	r->count = *count;
	r->clipped_position = *clipped_position;
	r->clipped_velocity = *clipped_velocity;
	if (*count > 0)
		memcpy(r->planes, collisions, *count * sizeof(*collisions));
	r->cluster_count = psp_sr_cluster_count;
	if (psp_sr_cluster_count > 0) /* -1: too many, none copied */
		memcpy(r->clusters, psp_sr_cluster_list, psp_sr_cluster_count * sizeof(short));
	r->biped_index = biped_index;
	psp_sr_counts[4]++;
}

""" + head, 1)
